    window.adicionarCategoria = async function () {
        const sel = document.getElementById("sel_nova_categoria");
        const catId = sel?.value;
        if (!catId) { mostrarAlerta("Selecione uma categoria."); return; }
        try {
            const res = await fetch(`${API}/categorias/${catId}/usuarios/${userId}`, { method: "POST" });
            if (!res.ok) { mostrarAlerta(`Erro ao adicionar categoria (HTTP ${res.status}).`); return; }
            sel.value = "";
            await carregarCategorias();
            window.dispatchEvent(new Event('xp:refresh'));
            mostrarAlerta("Categoria adicionada com sucesso!");
        } catch (e) {
            mostrarAlerta("Erro ao adicionar categoria.");
            console.error(e);
        }
    };

    window.abrirPersonalizada = function (tipo) {
        tipoPersonalizada = tipo;
        const modal  = document.getElementById("modalPersonalizada");
        const titulo = document.getElementById("modalPersonalizadaTitulo");
        const label  = document.getElementById("modalPersonalizadaLabel");
        const input  = document.getElementById("ipt_personalizada");
        if (tipo === "instituicao") {
            if (titulo) titulo.textContent = "Nova Instituição Personalizada";
            if (label)  label.textContent  = "Nome da instituição";
        } else {
            if (titulo) titulo.textContent = "Nova Categoria Personalizada";
            if (label)  label.textContent  = "Nome da categoria";
        }
        if (input) input.value = "";
        if (modal) modal.style.display = "flex";
    };

    window.fecharPersonalizada = function () {
        const modal = document.getElementById("modalPersonalizada");
        if (modal) modal.style.display = "none";
        tipoPersonalizada = null;
    };

    window.salvarPersonalizada = async function () {
        const input = document.getElementById("ipt_personalizada");
        const nome = input?.value?.trim();
        if (!nome) { mostrarAlerta("Informe o nome."); return; }
        try {
            if (tipoPersonalizada === "instituicao") {
                const resCreate = await postJson(`${API}/instituicoes`, { nome });
                if (!resCreate.ok) { mostrarAlerta("Erro ao criar instituição."); return; }
                const nova = await resCreate.json();
                const resLink = await fetch(`${API}/instituicoes/${nova.id}/usuarios/${userId}`, { method: "POST" });
                if (!resLink.ok) { mostrarAlerta("Erro ao vincular instituição."); return; }
                fecharPersonalizada();
                await carregarInstituicoes();
                window.dispatchEvent(new Event('xp:refresh'));
                mostrarAlerta("Instituição criada e vinculada com sucesso!");
            } else {
                const res = await postJson(`${API}/categorias/usuario/${userId}`, { titulo: nome });
                if (!res.ok) { mostrarAlerta("Erro ao criar categoria."); return; }
                fecharPersonalizada();
                await carregarCategorias();
                window.dispatchEvent(new Event('xp:refresh'));
                mostrarAlerta("Categoria personalizada criada com sucesso!");
            }
        } catch (e) {
            mostrarAlerta("Erro ao salvar.");
            console.error(e);
        }
    };

    window.removerCategoria = async function (catId) {
        try {
            await fetch(`${API}/categorias/${catId}/usuarios/${userId}`, { method: "PATCH" });
            await carregarCategorias();
        } catch (e) {
            mostrarAlerta("Erro ao remover categoria.");
            console.error(e);
        }
    };

    // ── IMPORTAR DADOS ────────────────────────────────────────────
    function garantirModalImportacao() {
        let modal = document.getElementById("cfgImportModal");
        if (modal) return modal;

        modal = document.createElement("div");
        modal.id = "cfgImportModal";
        // Estilo inline completo para garantir funcionamento em JavaFX WebView
        modal.style.cssText = [
            "display:none",
            "position:fixed",
            "inset:0",
            "background:rgba(0,0,0,0.55)",
            "z-index:9999",
            "align-items:center",
            "justify-content:center",
            "padding:16px"
        ].join(";");

        modal.innerHTML = `
            <div style="background:var(--cor-fundo-card,#FAFFFF);border-radius:20px;padding:28px 24px;
                        width:min(480px,94vw);display:flex;flex-direction:column;gap:16px;
                        box-shadow:0 8px 32px rgba(0,0,0,0.3);">
                <div style="display:flex;justify-content:space-between;align-items:center;">
                    <h2 style="margin:0;color:var(--cor-titulo,#004C58);font-size:1.4rem;">Importar dados</h2>
                    <button id="cfgImportFechar" style="background:none;border:1px solid #9cc9c9;border-radius:8px;
                            width:36px;height:36px;font-size:1.5rem;cursor:pointer;color:var(--cor-principal,#367373);
                            display:flex;align-items:center;justify-content:center;padding:0;margin:0;">&times;</button>
                </div>
                <p style="margin:0;color:var(--cor-texto-secundario,#4A4A4A);font-size:0.9rem;">
                    Selecione a instituição financeira e o arquivo exportado pelo banco.
                </p>

                <div style="position:relative;margin:4px 0;">
                    <select id="cfgImportBanco" style="height:52px;width:100%;border:2px solid var(--cor-principal,#367373);
                            border-radius:10px;padding:0 18px;font-size:1rem;font-weight:600;
                            color:var(--cor-principal,#367373);background:transparent;appearance:none;outline:none;">
                        <option value="" disabled selected>Selecione a instituição</option>
                    </select>
                    <span style="position:absolute;right:14px;top:50%;transform:translateY(-50%);
                                 color:var(--cor-principal,#367373);pointer-events:none;">▾</span>
                </div>

                <div style="border:2px dashed var(--cor-principal,#367373);border-radius:10px;
                            padding:16px;text-align:center;cursor:pointer;" id="cfgImportDropArea">
                    <p style="margin:0 0 8px;color:var(--cor-principal,#367373);font-weight:600;">
                        Clique para selecionar o arquivo
                    </p>
                    <p style="margin:0;font-size:0.8rem;color:var(--cor-texto-secundario,#4A4A4A);">
                        Formatos aceitos: .csv, .ofx, .xls, .xlsx, .json, .sql
                    </p>
                    <input type="file" id="cfgImportArquivo"
                           accept=".csv,.ofx,.qfx,.xls,.xlsx,.json,.sql,.pdf"
                           style="display:none;">
                    <p id="cfgImportNomeArquivo" style="margin:8px 0 0;font-size:0.85rem;
                       color:var(--cor-principal,#367373);font-weight:600;"></p>
                </div>

                <p id="cfgImportMsg" style="color:#e53e3e;font-size:0.85rem;display:none;margin:0;"></p>

                <div style="display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap;">
                    <button id="cfgImportCancelar"
                        style="height:44px;padding:0 20px;background:transparent;
                               border:2px solid var(--cor-principal,#367373);color:var(--cor-principal,#367373);
                               border-radius:10px;font-size:1rem;cursor:pointer;margin:0;">
                        Cancelar
                    </button>
                    <button id="cfgImportConfirmar"
                        style="height:44px;padding:0 20px;background:var(--cor-principal,#367373);
                               color:#fff;border:none;border-radius:10px;font-size:1rem;cursor:pointer;margin:0;">
                        Importar
                    </button>
                </div>
            </div>
        `;

        document.body.appendChild(modal);

        const fechar = () => { modal.style.display = "none"; };
        modal.querySelector("#cfgImportFechar").onclick = fechar;
        modal.querySelector("#cfgImportCancelar").onclick = fechar;
        modal.addEventListener("click", e => { if (e.target === modal) fechar(); });

        // Área de drop / clique para selecionar arquivo
        const dropArea = modal.querySelector("#cfgImportDropArea");
        const inputArq = modal.querySelector("#cfgImportArquivo");
        const nomeLabel = modal.querySelector("#cfgImportNomeArquivo");

        dropArea.addEventListener("click", () => inputArq.click());

        inputArq.addEventListener("change", () => {
            const f = inputArq.files && inputArq.files[0];
            nomeLabel.textContent = f ? `Arquivo selecionado: ${f.name}` : "";
        });

        modal.querySelector("#cfgImportConfirmar").onclick = async () => {
            const selBanco = modal.querySelector("#cfgImportBanco");
            const msg = modal.querySelector("#cfgImportMsg");
            const btn = modal.querySelector("#cfgImportConfirmar");

            const bancoId = selBanco ? selBanco.value : "";
            // O backend espera o NOME da instituição, não o ID
            const bancoNome = selBanco && selBanco.selectedIndex >= 0
                ? selBanco.options[selBanco.selectedIndex].textContent.trim()
                : "";
            const arquivo = inputArq && inputArq.files && inputArq.files[0];

            if (!bancoId) {
                msg.textContent = "Selecione uma instituição financeira.";
                msg.style.display = "";
                return;
            }
            if (!arquivo) {
                msg.textContent = "Selecione um arquivo para importar.";
                msg.style.display = "";
                return;
            }

            msg.style.display = "none";
            btn.disabled = true;
            btn.textContent = "Importando...";
            btn.style.opacity = "0.7";

            try {
                const formData = new FormData();
                // O backend espera: @RequestParam MultipartFile arquivo
                //                   @RequestParam(required = false) String bancoNome
                formData.append("arquivo", arquivo);
                if (bancoNome) formData.append("bancoNome", bancoNome);

                const res = await fetch(`${API}/configuracoes/upload-arquivo/usuarios/${userId}`, {
                    method: "POST",
                    body: formData
                });

                if (res.ok || res.status === 204) {
                    fechar();
                    mostrarAlerta("Dados importados com sucesso!");
                } else {
                    let detalhe = `HTTP ${res.status}`;
                    try { const corpo = await res.json(); detalhe = corpo.message || detalhe; } catch (_) {}
                    msg.textContent = `Erro ao importar: ${detalhe}`;
                    msg.style.display = "";
                }
            } catch (e) {
                console.error("Erro ao importar dados:", e);
                msg.textContent = "Erro de conexão ao importar. Verifique se o servidor está ativo.";
                msg.style.display = "";
            } finally {
                btn.disabled = false;
                btn.textContent = "Importar";
                btn.style.opacity = "1";
            }
        };

        return modal;
    }

    window.importarDados = function () {
        if (!userId) { mostrarAlerta("Usuário não identificado."); return; }

        const modal = garantirModalImportacao();
        const selBanco = modal.querySelector("#cfgImportBanco");
        const inputArq = modal.querySelector("#cfgImportArquivo");
        const nomeLabel = modal.querySelector("#cfgImportNomeArquivo");
        const msg = modal.querySelector("#cfgImportMsg");

        // Atualiza lista de instituições sempre que abrir
        if (selBanco) {
            selBanco.innerHTML = `<option value="" disabled selected>Selecione a instituição</option>`;
            (instituicoes || []).forEach(inst => {
                const opt = document.createElement("option");
                opt.value = inst.id;
                opt.textContent = (inst.intituicao && inst.intituicao.nome) ? inst.intituicao.nome : "Instituição";
                selBanco.appendChild(opt);
            });
        }
        if (inputArq) inputArq.value = "";
        if (nomeLabel) nomeLabel.textContent = "";
        if (msg) msg.style.display = "none";

        modal.style.display = "flex";
    };

    window.processarImportacao = function () {
        // Mantido por compatibilidade – fluxo agora via modal
    };

    function obterFormatosExportacaoDisponiveis() {
        return [
            { tipo: "pdf", label: "PDF (.pdf)" },
            { tipo: "excel", label: "Excel (.xlsx)" },
            { tipo: "json", label: "JSON (.json)" },
            { tipo: "sql", label: "SQL (.sql)" }
        ];
    }

    function garantirModalExportacao() {
        let modal = document.getElementById("cfgExportModal");
        if (modal) return modal;

        modal = document.createElement("div");
        modal.id = "cfgExportModal";
        modal.className = "modal";
        modal.style.display = "none";
        modal.innerHTML = `
            <div class="conteudoModal" style="max-width:460px;">
                <span id="cfgExportFechar" class="fechar" style="cursor:pointer;">&times;</span>
                <h2 style="margin-top:0; color:#0e5454;">Exportar dados</h2>
                <p style="margin:0 0 12px 0; color:#486468;">Selecione o formato do arquivo:</p>
                <div style="display:flex; flex-direction:column; gap:10px;">
                    <select id="cfgExportTipo" class="select_modal"></select>
                    <div style="display:flex; gap:10px; justify-content:flex-end;">
                        <button id="cfgExportCancelar" class="cfg-btn" style="background:transparent;border:2px solid var(--cor-principal);color:var(--cor-principal);">Cancelar</button>
                        <button id="cfgExportConfirmar" class="cfg-btn">Exportar</button>
                    </div>
                </div>
            </div>
        `;

        document.body.appendChild(modal);

        const fechar = () => { modal.style.display = "none"; };
        const btnFechar = document.getElementById("cfgExportFechar");
        const btnCancelar = document.getElementById("cfgExportCancelar");
        if (btnFechar) btnFechar.onclick = fechar;
        if (btnCancelar) btnCancelar.onclick = fechar;

        modal.addEventListener("click", (event) => {
            if (event.target === modal) {
                fechar();
            }
        });

        const btnConfirmar = document.getElementById("cfgExportConfirmar");
        if (btnConfirmar) {
            btnConfirmar.onclick = async () => {
                const select = document.getElementById("cfgExportTipo");
                const tipo = select?.value;
                if (!tipo) {
                    mostrarAlerta("Selecione um formato para exportação.");
                    return;
                }
                modal.style.display = "none";
                await exportarDadosPorTipo(tipo);
            };
        }

        return modal;
    }

    function abrirModalExportacao() {
        const modal = garantirModalExportacao();
        const select = document.getElementById("cfgExportTipo");
        if (!select) return;

        const formatos = obterFormatosExportacaoDisponiveis();
        select.innerHTML = formatos
            .map(f => `<option value="${f.tipo}">${f.label}</option>`)
            .join("");

        modal.style.display = "flex";
    }

    async function aguardarDesktopBridge(timeoutMs = 1800, intervaloMs = 120) {
        const inicio = Date.now();
        while (Date.now() - inicio < timeoutMs) {
            if (window.desktopBridge) {
                return window.desktopBridge;
            }
            await new Promise(resolve => setTimeout(resolve, intervaloMs));
        }
        return window.desktopBridge || null;
    }

    // ── MODAL DE DOWNLOAD MANUAL (fallback para JavaFX) ──────────
    function mostrarModalDownload(url, nome, tipo) {
        const anterior = document.getElementById("cfgModalDownload");
        if (anterior) anterior.remove();

        const modal = document.createElement("div");
        modal.id = "cfgModalDownload";
        modal.style.cssText = [
            "position:fixed", "inset:0", "background:rgba(0,0,0,0.55)",
            "z-index:9999", "display:flex", "align-items:center",
            "justify-content:center", "padding:16px"
        ].join(";");

        modal.innerHTML = `
            <div style="background:var(--cor-fundo-card,#FAFFFF);border-radius:20px;padding:28px 24px;
                        width:min(520px,96vw);display:flex;flex-direction:column;gap:16px;
                        box-shadow:0 8px 32px rgba(0,0,0,0.3);">
                <div style="display:flex;align-items:center;gap:10px;">
                    <i class='bx bx-download' style="font-size:1.8rem;color:var(--cor-principal,#367373);"></i>
                    <h3 style="margin:0;color:var(--cor-titulo,#004C58);font-size:1.3rem;">
                        Exportar ${tipo.toUpperCase()}
                    </h3>
                </div>

                <p style="margin:0;font-size:0.9rem;color:var(--cor-texto-secundario,#4A4A4A);line-height:1.5;">
                    Clique em <strong>"Baixar arquivo"</strong> para iniciar o download.
                    Se não funcionar automaticamente, copie o link e abra no navegador do sistema.
                </p>

                <div style="background:var(--cor-fundo-pagina,#EBF4F4);border-radius:10px;padding:10px 14px;
                            word-break:break-all;font-size:0.78rem;font-family:monospace;
                            color:var(--cor-texto-principal,#1A1A1A);border:1px solid var(--cor-hover,#B4D9D5);">
                    ${url}
                </div>

                <div style="display:flex;gap:10px;flex-wrap:wrap;">
                    <button id="cfgDlBaixar"
                        style="flex:2;min-width:140px;height:46px;background:var(--cor-principal,#367373);
                               color:#fff;border:none;border-radius:10px;font-size:0.95rem;
                               cursor:pointer;font-weight:600;margin:0;display:flex;
                               align-items:center;justify-content:center;gap:6px;">
                        <i class='bx bx-download'></i> Baixar arquivo
                    </button>
                    <button id="cfgDlCopiar"
                        style="flex:1;min-width:110px;height:46px;background:transparent;
                               color:var(--cor-principal,#367373);border:2px solid var(--cor-principal,#367373);
                               border-radius:10px;font-size:0.95rem;cursor:pointer;margin:0;">
                        Copiar link
                    </button>
                    <button id="cfgDlFechar"
                        style="height:46px;padding:0 14px;background:transparent;color:#888;
                               border:1px solid #ccc;border-radius:10px;font-size:0.9rem;
                               cursor:pointer;margin:0;">
                        Fechar
                    </button>
                </div>

                <p style="margin:0;font-size:0.78rem;color:#888;line-height:1.4;">
                     <em>Dica IntelliJ/JavaFX:</em> se o download não abrir automaticamente,
                    copie o link acima e cole em um navegador (Chrome, Firefox etc.).
                </p>
            </div>
        `;

        document.body.appendChild(modal);

        const fechar = () => modal.remove();
        modal.querySelector("#cfgDlFechar").onclick = fechar;
        modal.addEventListener("click", e => { if (e.target === modal) fechar(); });

        // Botão COPIAR
        modal.querySelector("#cfgDlCopiar").onclick = function () {
            const btn = this;
            const copiar = () => {
                const ta = document.createElement("textarea");
                ta.value = url;
                ta.style.cssText = "position:fixed;top:-9999px;left:-9999px;";
                document.body.appendChild(ta);
                ta.focus();
                ta.select();
                try { document.execCommand("copy"); } catch (_) {}
                ta.remove();
            };
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(url).catch(copiar);
            } else {
                copiar();
            }
            btn.textContent = "✓ Copiado!";
            setTimeout(() => { btn.textContent = "Copiar link"; }, 2000);
        };

        // Botão BAIXAR — tenta todos os métodos disponíveis
        modal.querySelector("#cfgDlBaixar").onclick = function () {
            const btn = this;
            btn.textContent = "Iniciando...";
            btn.disabled = true;

            // Método 1: window.location.href (JavaFX WebEngine: pode disparar download handler)
            // Usamos um timeout para não travar a UI
            setTimeout(() => {
                try { window.open(url, "_blank"); } catch (_) {}
            }, 0);

            setTimeout(() => {
                // Método 2: a.click() direto na URL (sem blob)
                const a = document.createElement("a");
                a.href = url;
                a.download = nome;
                a.style.display = "none";
                document.body.appendChild(a);
                a.click();
                a.remove();
            }, 150);

            setTimeout(() => {
                // Método 3: navigate (pode ser interceptado pelo loadWorker do JavaFX)
                window.location.href = url;
            }, 500);

            setTimeout(() => {
                btn.disabled = false;
                btn.innerHTML = "<i class='bx bx-download'></i> Baixar arquivo";
            }, 3000);
        };
    }

    async function exportarDadosPorTipo(tipo) {
        if (!userId) {
            mostrarAlerta("Usuário não identificado para exportação.");
            return;
        }

        const ext = tipo === "excel" ? "xlsx" : tipo;
        let nomeArquivo = `registros.${ext}`;
        const downloadUrl = `${API}/registros/download/${userId}?tipo=${encodeURIComponent(tipo)}`;

        // 1. desktopBridge (JavaFX bridge nativo — se disponível)
        const bridge = await aguardarDesktopBridge(2000);
        if (bridge) {
            try {
                const res = await fetch(downloadUrl);
                if (!res.ok) { mostrarAlerta(`Erro ao exportar (HTTP ${res.status}).`); return; }
                const blob = await res.blob();
                const cd = res.headers.get("content-disposition") || "";
                const m = cd.match(/filename=([^;]+)/i);
                if (m && m[1]) nomeArquivo = m[1].replace(/"/g, "").trim();

                const bytes = new Uint8Array(await blob.arrayBuffer());
                let binario = "";
                for (let i = 0; i < bytes.length; i += 0x8000) {
                    binario += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
                }
                const salvo = bridge.saveBase64File(nomeArquivo, btoa(binario));
                if (salvo) { mostrarAlerta(`${tipo.toUpperCase()} exportado com sucesso!`); return; }
            } catch (bridgeErr) {
                console.warn("desktopBridge falhou:", bridgeErr);
            }
        }

        // 2. Verifica se o endpoint responde
        try {
            const check = await fetch(downloadUrl, { method: "HEAD" });
            if (!check.ok) {
                mostrarAlerta(`Servidor retornou erro ao gerar o arquivo (HTTP ${check.status}).`);
                return;
            }
        } catch (e) {
            console.warn("HEAD check falhou:", e);
        }

        // 3. Busca conteúdo e tenta abordagens JavaScript
        let blob = null;
        try {
            const res = await fetch(downloadUrl);
            if (res.ok) {
                blob = await res.blob();
                const cd = res.headers.get("content-disposition") || "";
                const m = cd.match(/filename=([^;]+)/i);
                if (m && m[1]) nomeArquivo = m[1].replace(/"/g, "").trim();
            }
        } catch (e) {
            console.warn("Fetch do blob falhou:", e);
        }

        if (blob) {
            // 3a. Blob URL (funciona em browsers normais)
            try {
                const blobUrl = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = blobUrl;
                a.download = nomeArquivo;
                a.style.display = "none";
                document.body.appendChild(a);
                a.click();
                a.remove();
                setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
            } catch (e) { console.warn("Blob URL:", e); }

            // 3b. Data URI (às vezes funciona em JavaFX quando blob URL falha)
            try {
                const arrayBuffer = await blob.arrayBuffer();
                const bytes = new Uint8Array(arrayBuffer);
                let binary = "";
                for (let i = 0; i < bytes.length; i += 0x8000) {
                    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
                }
                const base64 = btoa(binary);
                const mimeType = blob.type || "application/octet-stream";
                const dataUri = `data:${mimeType};base64,${base64}`;

                const a2 = document.createElement("a");
                a2.href = dataUri;
                a2.download = nomeArquivo;
                a2.style.display = "none";
                document.body.appendChild(a2);
                a2.click();
                a2.remove();
            } catch (e) { console.warn("Data URI:", e); }
        }

        // 4. Em JavaFX: iframe (WebEngine pode acionar loadWorker → download handler)
        setTimeout(() => {
            try {
                const ifr = document.createElement("iframe");
                ifr.style.cssText = "display:none;width:0;height:0;border:0;";
                ifr.src = downloadUrl;
                document.body.appendChild(ifr);
                setTimeout(() => { try { document.body.removeChild(ifr); } catch (_) {} }, 60000);
            } catch (e) { console.warn("Iframe:", e); }
        }, 300);

        // 5. Mostra modal com link direto + botões (fallback confiável para JavaFX)
        setTimeout(() => {
            mostrarModalDownload(downloadUrl, nomeArquivo, tipo);
        }, 800);
    }

    window.exportarDados = function () {
        abrirModalExportacao();
    };


    // ── CALENDÁRIO – SELEÇÃO DE PERÍODO PARA EXCLUSÃO ────────────
    let cfgCalCampo = null;        // 'inicio' | 'fim'
    let cfgCalDataSelecionada = null;
    let cfgDeleteInicio = null;    // YYYY-MM-DD
    let cfgDeleteFim    = null;    // YYYY-MM-DD

    let cfgCalMesAtual  = new Date().getMonth();
    let cfgCalAnoAtual  = new Date().getFullYear();

    function cfgCalFormatar(iso) {
        const [a, m, d] = iso.split("-");
        return `${d}/${m}/${a}`;
    }

    function cfgCalGerar() {
        const dias    = document.getElementById("cfgCalDias");
        const mesAno  = document.getElementById("cfgCalMesAno");
        const confirmar = document.getElementById("cfgCalConfirmar");
        if (!dias) return;

        dias.innerHTML = "";
        cfgCalDataSelecionada = null;
        if (confirmar) confirmar.disabled = true;

        mesAno.innerText = new Date(cfgCalAnoAtual, cfgCalMesAtual)
            .toLocaleString("pt-BR", { month: "long", year: "numeric" });

        const primeiroDia = new Date(cfgCalAnoAtual, cfgCalMesAtual, 1).getDay();
        const totalDias   = new Date(cfgCalAnoAtual, cfgCalMesAtual + 1, 0).getDate();

        for (let i = 0; i < primeiroDia; i++) dias.innerHTML += `<span></span>`;

        for (let dia = 1; dia <= totalDias; dia++) {
            const iso = `${cfgCalAnoAtual}-${String(cfgCalMesAtual + 1).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
            const span = document.createElement("span");
            span.innerText = dia;
            span.onclick = () => {
                dias.querySelectorAll(".diaSelecionado").forEach(e => e.classList.remove("diaSelecionado"));
                span.classList.add("diaSelecionado");
                cfgCalDataSelecionada = iso;
                if (confirmar) confirmar.disabled = false;
            };
            dias.appendChild(span);
        }
    }

    window.abrirCalendarioDelete = function (campo) {
        cfgCalCampo = campo;
        cfgCalMesAtual = new Date().getMonth();
        cfgCalAnoAtual = new Date().getFullYear();
        const modal = document.getElementById("cfgCalModal");
        if (modal) { modal.style.display = "flex"; cfgCalGerar(); }
    };

    document.addEventListener("DOMContentLoaded", () => {
        const fechar    = document.getElementById("cfgCalFechar");
        const anterior  = document.getElementById("cfgCalAnterior");
        const proximo   = document.getElementById("cfgCalProximo");
        const confirmar = document.getElementById("cfgCalConfirmar");
        const modal     = document.getElementById("cfgCalModal");

        if (fechar)    fechar.onclick   = () => { if (modal) modal.style.display = "none"; };
        if (anterior)  anterior.onclick = () => {
            cfgCalMesAtual--;
            if (cfgCalMesAtual < 0) { cfgCalMesAtual = 11; cfgCalAnoAtual--; }
            cfgCalGerar();
        };
        if (proximo)   proximo.onclick  = () => {
            cfgCalMesAtual++;
            if (cfgCalMesAtual > 11) { cfgCalMesAtual = 0; cfgCalAnoAtual++; }
            cfgCalGerar();
        };
        if (confirmar) confirmar.onclick = () => {
            if (!cfgCalDataSelecionada) return;
            if (cfgCalCampo === "inicio") {
                cfgDeleteInicio = cfgCalDataSelecionada;
                const lbl = document.getElementById("cfgDeleteInicioLabel");
                if (lbl) lbl.textContent = cfgCalFormatar(cfgDeleteInicio);
            } else {
                cfgDeleteFim = cfgCalDataSelecionada;
                const lbl = document.getElementById("cfgDeleteFimLabel");
                if (lbl) lbl.textContent = cfgCalFormatar(cfgDeleteFim);
            }
            if (modal) modal.style.display = "none";
        };
    });

    // ── APAGAR REGISTROS ─────────────────────────────────────────
    window.apagarRegistrosPeriodo = function () {
        if (!cfgDeleteInicio || !cfgDeleteFim) {
            mostrarAlerta("Escolha a data inicial e a data final do período.");
            return;
        }
        if (cfgDeleteInicio > cfgDeleteFim) {
            mostrarAlerta("A data inicial não pode ser maior que a data final.");
            return;
        }
        if (!cfgId) {
            mostrarAlerta("Configuração do usuário não carregada.");
            return;
        }

        mostrarConfirmacao(
            `Apagar todos os registros de ${cfgCalFormatar(cfgDeleteInicio)} até ${cfgCalFormatar(cfgDeleteFim)}? Esta ação é irreversível.`,
            async () => {
                try {
                    const res = await fetch(`${API}/configuracoes/${cfgId}/dados/periodo-tempo`, {
                        method: "DELETE",
                        headers: { "Content-Type": "application/json" },
                        body: JSON.stringify({ dataInical: cfgDeleteInicio, dataFinal: cfgDeleteFim })
                    });
                    if (res.status === 204) {
                        mostrarAlerta("Registros do período apagados com sucesso!");
                        cfgDeleteInicio = cfgDeleteFim = null;
                        const lI = document.getElementById("cfgDeleteInicioLabel");
                        const lF = document.getElementById("cfgDeleteFimLabel");
                        if (lI) lI.textContent = "";
                        if (lF) lF.textContent = "";
                    } else {
                        const txt = await res.text();
                        mostrarAlerta(`Erro ao apagar registros (HTTP ${res.status}): ${txt}`);
                    }
                } catch (e) {
                    console.error("Erro ao apagar registros por período:", e);
                    mostrarAlerta("Erro ao apagar registros do período.");
                }
            }
        );
    };

    window.apagarTodosRegistros = function () {
        if (!userId) {
            mostrarAlerta("Usuário não identificado.");
            return;
        }

        mostrarConfirmacao(
            "Apagar TODOS os registros do usuário? Esta ação é irreversível.",
            async () => {
                try {
                    const res = await fetch(`${API}/configuracoes/usuarios/${userId}/dados/deletar-tudo`, {
                        method: "DELETE"
                    });
                    if (res.status === 204) {
                        mostrarAlerta("Todos os registros foram apagados com sucesso!");
                    } else {
                        const txt = await res.text();
                        mostrarAlerta(`Erro ao apagar registros (HTTP ${res.status}): ${txt}`);
                    }
                } catch (e) {
                    console.error("Erro ao apagar todos os registros:", e);
                    mostrarAlerta("Erro ao apagar todos os registros.");
                }
            }
        );
    };

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", init);
    } else {
        init();
    }
})();

package controle.api.back_end.controller;

import controle.api.back_end.dto.emprestimo.in.EmprestimoCreateDTO;
import controle.api.back_end.dto.emprestimo.in.EmprestimoPagamentoParcialDTO;
import controle.api.back_end.dto.emprestimo.out.EmprestimoResponseDTO;
import controle.api.back_end.dto.emprestimo.out.EmprestimoResumoDTO;
import controle.api.back_end.model.emprestimo.TipoEmprestimo;
import controle.api.back_end.service.EmprestimoService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.UUID;

@CrossOrigin
@RestController
@RequestMapping("/emprestimos")
@Tag(name = "Empréstimos",
     description = "Gerenciamento de empréstimos feitos pelo usuário ou recebidos. " +
                   "Controla quanto você emprestou para outras pessoas e quanto você deve.")
public class EmprestimoController {

    private final EmprestimoService emprestimoService;

    public EmprestimoController(EmprestimoService emprestimoService) {
        this.emprestimoService = emprestimoService;
    }

    // =========================================================================
    // CRIAR
    // =========================================================================

    @PostMapping
    @Operation(summary = "Criar um novo empréstimo",
               description = """
                       Registra um empréstimo feito ou recebido.

                       **Tipos:**
                       - `EMPRESTEI` – você emprestou dinheiro/cartão para alguém
                       - `PEDI_EMPRESTADO` – você pegou dinheiro emprestado de alguém

                       O status inicial é sempre `PENDENTE`.
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "201", description = "Empréstimo criado com sucesso.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "400", description = "Dados inválidos.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> criar(@Valid @RequestBody EmprestimoCreateDTO dto) {
        return ResponseEntity.status(201).body(emprestimoService.criar(dto));
    }

    // =========================================================================
    // CONSULTAS
    // =========================================================================

    @GetMapping("/usuarios/{usuarioId}")
    @Operation(summary = "Listar todos os empréstimos do usuário",
               description = "Retorna todos os empréstimos (pendentes, parciais e quitados) ordenados por data de criação.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo encontrado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarPorUsuario(@PathVariable UUID usuarioId) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarPorUsuario(usuarioId);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/usuarios/{usuarioId}/nao-quitados")
    @Operation(summary = "Listar empréstimos não quitados",
               description = "Retorna apenas empréstimos com status PENDENTE ou PAGO_PARCIAL.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos não quitados.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo não quitado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarNaoQuitados(@PathVariable UUID usuarioId) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarNaoQuitados(usuarioId);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/usuarios/{usuarioId}/tipo/{tipo}")
    @Operation(summary = "Listar empréstimos por tipo",
               description = "Filtra empréstimos por EMPRESTEI ou PEDI_EMPRESTADO.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos do tipo especificado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo encontrado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarPorTipo(
            @PathVariable UUID usuarioId,
            @PathVariable TipoEmprestimo tipo) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarPorTipo(usuarioId, tipo);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/{emprestimoId}")
    @Operation(summary = "Buscar empréstimo por ID",
               description = "Retorna os dados completos de um empréstimo específico.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo encontrado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> buscarPorId(@PathVariable UUID emprestimoId) {
        return ResponseEntity.ok(emprestimoService.buscarPorId(emprestimoId));
    }

    @GetMapping("/usuarios/{usuarioId}/resumo")
    @Operation(summary = "Obter resumo de empréstimos",
               description = """
                       Retorna um resumo consolidado:
                       - Quantas pessoas devem ao usuário e o valor total a receber
                       - Quantas pessoas o usuário deve e o valor total a pagar

                       Útil para exibir notificações na tela inicial.
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Resumo calculado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResumoDTO.class))),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResumoDTO> obterResumo(@PathVariable UUID usuarioId) {
        return ResponseEntity.ok(emprestimoService.obterResumo(usuarioId));
    }

    // =========================================================================
    // ATUALIZAR
    // =========================================================================

    @PutMapping("/{emprestimoId}")
    @Operation(summary = "Editar um empréstimo",
               description = "Atualiza os dados do empréstimo. O status é recalculado automaticamente.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo atualizado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> editar(
            @PathVariable UUID emprestimoId,
            @Valid @RequestBody EmprestimoCreateDTO dto) {
        return ResponseEntity.ok(emprestimoService.editar(emprestimoId, dto));
    }

    @PatchMapping("/{emprestimoId}/pagamento-parcial")
    @Operation(summary = "Registrar pagamento parcial",
               description = """
                       Adiciona um valor ao campo `valorPago` do empréstimo.
                       O status é atualizado automaticamente:
                       - Se valorPago = valorTotal → QUITADO
                       - Se 0 < valorPago < valorTotal → PAGO_PARCIAL
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Pagamento registrado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "400", description = "Valor inválido.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> registrarPagamentoParcial(
            @PathVariable UUID emprestimoId,
            @Valid @RequestBody EmprestimoPagamentoParcialDTO dto) {
        return ResponseEntity.ok(emprestimoService.registrarPagamentoParcial(emprestimoId, dto));
    }

    @PatchMapping("/{emprestimoId}/quitar")
    @Operation(summary = "Marcar como quitado",
               description = "Define o empréstimo como totalmente pago, ajustando valorPago = valorTotal e status = QUITADO.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo quitado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> marcarComoQuitado(@PathVariable UUID emprestimoId) {
        return ResponseEntity.ok(emprestimoService.marcarComoQuitado(emprestimoId));
    }

    @PatchMapping("/{emprestimoId}/reabrir")
    @Operation(summary = "Reabrir empréstimo quitado",
               description = "Desfaz a quitação, voltando o status para PENDENTE e zerando o valorPago.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo reaberto.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> reabrir(@PathVariable UUID emprestimoId) {
        return ResponseEntity.ok(emprestimoService.reabrir(emprestimoId));
    }

    // =========================================================================
    // DELETAR
    // =========================================================================

    @DeleteMapping("/{emprestimoId}")
    @Operation(summary = "Deletar um empréstimo",
               description = "Remove permanentemente o registro de empréstimo.")
    @ApiResponses({
            @ApiResponse(responseCode = "204", description = "Empréstimo deletado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<Void> deletar(@PathVariable UUID emprestimoId) {
        emprestimoService.deletar(emprestimoId);
        return ResponseEntity.noContent().build();
    }
}

package controle.api.back_end.controller;

import controle.api.back_end.dto.emprestimo.in.EmprestimoCreateDTO;
import controle.api.back_end.dto.emprestimo.in.EmprestimoPagamentoParcialDTO;
import controle.api.back_end.dto.emprestimo.in.EmprestimoQuitarDTO;
import controle.api.back_end.dto.emprestimo.out.EmprestimoResponseDTO;
import controle.api.back_end.dto.emprestimo.out.EmprestimoResumoDTO;
import controle.api.back_end.model.emprestimo.TipoEmprestimo;
import controle.api.back_end.service.EmprestimoService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;
import java.util.UUID;

@CrossOrigin
@RestController
@RequestMapping("/emprestimos")
@Tag(name = "Empréstimos",
     description = "Gerenciamento de empréstimos feitos pelo usuário ou recebidos. " +
                   "Controla quanto você emprestou para outras pessoas e quanto você deve.")
public class EmprestimoController {

    private final EmprestimoService emprestimoService;

    public EmprestimoController(EmprestimoService emprestimoService) {
        this.emprestimoService = emprestimoService;
    }

    // =========================================================================
    // CRIAR
    // =========================================================================

    @PostMapping
    @Operation(summary = "Criar um novo empréstimo",
               description = """
                       Registra um empréstimo feito ou recebido.

                       **Tipos:**
                       - `EMPRESTEI` – você emprestou dinheiro/cartão para alguém
                       - `PEDI_EMPRESTADO` – você pegou dinheiro emprestado de alguém

                       O status inicial é sempre `PENDENTE`.
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "201", description = "Empréstimo criado com sucesso.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "400", description = "Dados inválidos.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> criar(@Valid @RequestBody EmprestimoCreateDTO dto) {
        return ResponseEntity.status(201).body(emprestimoService.criar(dto));
    }

    // =========================================================================
    // CONSULTAS
    // =========================================================================

    @GetMapping("/usuarios/{usuarioId}")
    @Operation(summary = "Listar todos os empréstimos do usuário",
               description = "Retorna todos os empréstimos (pendentes, parciais e quitados) ordenados por data de criação.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo encontrado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarPorUsuario(@PathVariable UUID usuarioId) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarPorUsuario(usuarioId);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/usuarios/{usuarioId}/nao-quitados")
    @Operation(summary = "Listar empréstimos não quitados",
               description = "Retorna apenas empréstimos com status PENDENTE ou PAGO_PARCIAL.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos não quitados.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo não quitado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarNaoQuitados(@PathVariable UUID usuarioId) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarNaoQuitados(usuarioId);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/usuarios/{usuarioId}/tipo/{tipo}")
    @Operation(summary = "Listar empréstimos por tipo",
               description = "Filtra empréstimos por EMPRESTEI ou PEDI_EMPRESTADO.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Lista de empréstimos do tipo especificado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Nenhum empréstimo encontrado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<List<EmprestimoResponseDTO>> listarPorTipo(
            @PathVariable UUID usuarioId,
            @PathVariable TipoEmprestimo tipo) {
        List<EmprestimoResponseDTO> lista = emprestimoService.listarPorTipo(usuarioId, tipo);
        return lista.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(lista);
    }

    @GetMapping("/{emprestimoId}")
    @Operation(summary = "Buscar empréstimo por ID",
               description = "Retorna os dados completos de um empréstimo específico.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo encontrado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> buscarPorId(@PathVariable UUID emprestimoId) {
        return ResponseEntity.ok(emprestimoService.buscarPorId(emprestimoId));
    }

    @GetMapping("/usuarios/{usuarioId}/resumo")
    @Operation(summary = "Obter resumo de empréstimos",
               description = """
                       Retorna um resumo consolidado:
                       - Quantas pessoas devem ao usuário e o valor total a receber
                       - Quantas pessoas o usuário deve e o valor total a pagar

                       Útil para exibir notificações na tela inicial.
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Resumo calculado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResumoDTO.class))),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResumoDTO> obterResumo(@PathVariable UUID usuarioId) {
        return ResponseEntity.ok(emprestimoService.obterResumo(usuarioId));
    }

    // =========================================================================
    // ATUALIZAR
    // =========================================================================

    @PutMapping("/{emprestimoId}")
    @Operation(summary = "Editar um empréstimo",
               description = "Atualiza os dados do empréstimo. O status é recalculado automaticamente.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo atualizado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> editar(
            @PathVariable UUID emprestimoId,
            @Valid @RequestBody EmprestimoCreateDTO dto) {
        return ResponseEntity.ok(emprestimoService.editar(emprestimoId, dto));
    }

    @PatchMapping("/{emprestimoId}/pagamento-parcial")
    @Operation(summary = "Registrar pagamento parcial",
               description = """
                       Adiciona um valor ao campo `valorPago` do empréstimo.
                       O status é atualizado automaticamente:
                       - Se valorPago = valorTotal → QUITADO
                       - Se 0 < valorPago < valorTotal → PAGO_PARCIAL
                       """)
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Pagamento registrado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "400", description = "Valor inválido.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> registrarPagamentoParcial(
            @PathVariable UUID emprestimoId,
            @Valid @RequestBody EmprestimoPagamentoParcialDTO dto) {
        return ResponseEntity.ok(emprestimoService.registrarPagamentoParcial(emprestimoId, dto));
    }

    @PatchMapping("/{emprestimoId}/quitar")
    @Operation(summary = "Marcar como quitado",
               description = "Define o empréstimo como totalmente pago, ajustando valorPago = valorTotal e status = QUITADO.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo quitado.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> marcarComoQuitado(
            @PathVariable UUID emprestimoId,
            @Valid @RequestBody EmprestimoQuitarDTO dto) {
        return ResponseEntity.ok(emprestimoService.marcarComoQuitado(emprestimoId, dto));
    }

    @PatchMapping("/{emprestimoId}/reabrir")
    @Operation(summary = "Reabrir empréstimo quitado",
               description = "Desfaz a quitação, voltando o status para PENDENTE e zerando o valorPago.")
    @ApiResponses({
            @ApiResponse(responseCode = "200", description = "Empréstimo reaberto.",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = EmprestimoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<EmprestimoResponseDTO> reabrir(@PathVariable UUID emprestimoId) {
        return ResponseEntity.ok(emprestimoService.reabrir(emprestimoId));
    }

    // =========================================================================
    // DELETAR
    // =========================================================================

    @DeleteMapping("/{emprestimoId}")
    @Operation(summary = "Deletar um empréstimo",
               description = "Remove permanentemente o registro de empréstimo.")
    @ApiResponses({
            @ApiResponse(responseCode = "204", description = "Empréstimo deletado.", content = @Content),
            @ApiResponse(responseCode = "404", description = "Empréstimo não encontrado.", content = @Content)
    })
    public ResponseEntity<Void> deletar(@PathVariable UUID emprestimoId) {
        emprestimoService.deletar(emprestimoId);
        return ResponseEntity.noContent().build();
    }
}

package controle.api.back_end.controller;

import controle.api.back_end.dto.instituicao.in.AtualizarInstituicaoUsuarioDto;
import controle.api.back_end.dto.instituicao.in.InstituicaoCreateDTO;
import controle.api.back_end.dto.instituicao.out.DetalheInstituicaoDto;
import controle.api.back_end.dto.instituicao.out.InstituicaoResponseDTO;
import controle.api.back_end.dto.instituicao.out.InstituicaoUsuarioResponseDTO;
import controle.api.back_end.dto.instituicao.out.ResumoInstituicaoDto;
import controle.api.back_end.dto.instituicao.mapper.InstituicaoMapper;
import controle.api.back_end.dto.instituicao.mapper.InstituicaoUsuarioMapper;
import controle.api.back_end.model.instituicao.Instituicao;
import controle.api.back_end.model.instituicao.InstituicaoUsuario;
import controle.api.back_end.service.InstituicaoService;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.media.Content;
import io.swagger.v3.oas.annotations.media.Schema;
import io.swagger.v3.oas.annotations.responses.ApiResponse;
import io.swagger.v3.oas.annotations.responses.ApiResponses;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

@CrossOrigin
@RestController
@RequestMapping("/instituicoes")
@Tag(name = "Instituições", description = "Endpoints referentes as instituições financeiras dos usuários, por exemplo: itau, bradesco etc...")
public class InstituicaoController {

    private final InstituicaoService instituicaoService;

    public InstituicaoController(InstituicaoService instituicaoService) {
        this.instituicaoService = instituicaoService;
    }


    @GetMapping
    @Operation(summary = "Buscar todas as intituições ",
            description = "Busca todas as instituições registradas no banco de dados.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "Busca de dados feita com sucesso e retornou com dados",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = InstituicaoResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Busca de dados feita com sucesso e não retornou dados",
            content = @Content)
    })
    public ResponseEntity<Page<InstituicaoResponseDTO>> getInstituicoes(
            @RequestParam(defaultValue = "0") int pagina){
        Page<InstituicaoResponseDTO> response = instituicaoService
                .getInstituicoes(PageRequest.of(pagina, 5))
                .map(InstituicaoMapper::toDto);
        if(response.isEmpty()){
            return ResponseEntity.noContent().build();
        }
        return ResponseEntity.ok(response);
    }


    @GetMapping("/{id}")
    @Operation(summary = "Buscar a insituição que contém o id desejado ",
            description = "Busca no banco de dados a instituição com o id desejado.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "Busca de dados feita com sucesso e retornou com dados",
            content = @Content(mediaType = "application/json",
            schema = @Schema(implementation = InstituicaoResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Instituição não encontrada",
            content = @Content)
    })
    public ResponseEntity<InstituicaoResponseDTO> getInsituicaoById(@PathVariable Integer id){
        Instituicao entity = instituicaoService.getInstituicaoById(id);
        InstituicaoResponseDTO response = InstituicaoMapper.toDto(entity);
        return ResponseEntity.status(200).body(response);
    }

    @GetMapping("/saldo/{instituicaoUsuario_id}")
    @Operation(summary = "Buscar o saldo pelo id da instituição",
            description = "Busca o saldo de uma instituição pela assosiação do usuário e da instituição.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "Busca feita com sucesso e a dados para retornar",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = BigDecimal.class))),
            @ApiResponse(responseCode = "404", description = "Dados Inválidos",
                    content = @Content)
    })
    public ResponseEntity<BigDecimal> getSaldoByInstituicao(@PathVariable Integer instituicaoUsuario_id){
        BigDecimal saldoByInstituicao = instituicaoService
                .getSaldoByInstituicao(instituicaoUsuario_id);
        return ResponseEntity.status(200).body(saldoByInstituicao);
    }

    @PostMapping
    @Operation(summary = "Adicionar uma instituição.",
            description = "Cria uma nova instituição no banco de dados.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "201", description = "Instituição criada com sucesso!",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = InstituicaoResponseDTO.class))),
            @ApiResponse(responseCode = "400", description = "Dados inválidos.",
                    content = @Content)
    })
    public ResponseEntity<InstituicaoResponseDTO> createInstituicao(@Valid @RequestBody InstituicaoCreateDTO dto){
        Instituicao entity = InstituicaoMapper.toEntity(dto);
        Instituicao created = instituicaoService.createInstituicao(entity);
        InstituicaoResponseDTO response = InstituicaoMapper.toDto(created);
        return ResponseEntity.status(201).body(response);
    }

    @PostMapping("/{instituicao_id}/usuarios/{usuario_id}")
    @Operation(summary = "Vincular uma instituição a um usuario",
            description = "Vincular por meio de uma tabela associativa no banco de dados uma instituição a um usuario.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "201", description = "Instituição associada a um usuario com sucesso",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = InstituicaoUsuarioResponseDTO.class))),
            @ApiResponse(responseCode = "404", description = "Dados Inválidos",
                    content = @Content)
    })
    public ResponseEntity<InstituicaoUsuarioResponseDTO> createInstituicaoForUser(
            @PathVariable Integer instituicao_id,
            @PathVariable UUID usuario_id){
        InstituicaoUsuario created = instituicaoService.createInstituicaoForUsuario(instituicao_id, usuario_id);
        InstituicaoUsuarioResponseDTO response = InstituicaoUsuarioMapper.toDto(created);
        return ResponseEntity.status(201).body(response);
    }


    @PatchMapping("/{instituicao_id}/usuarios/{user_id}")
    @Operation(summary = "Desvincular uma instituição de um usuário",
            description = "Desativa o vinculo do usuario com a instituição.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "204", description = "Instituição desasociado do usuario com sucesso",
                    content = @Content),
            @ApiResponse(responseCode = "404", description = "Dados Inválidos",
                    content = @Content)
    })
    public ResponseEntity<List<InstituicaoUsuarioResponseDTO>> detachUserFromInstituicao(
            @PathVariable Integer instituicao_id,
            @PathVariable UUID user_id
    ){
        instituicaoService.detachUserFromInstituicao(instituicao_id,user_id);
        return ResponseEntity.status(204).build();
    }

    @GetMapping("/usuarios/{user_id}")
    @Operation(summary = "Buscar instituições pelo id do usuário",
            description = "Busca uma instituição que está associada a um usuário")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "Busca feita com sucesso e a dados para retornar",
                    content = @Content(mediaType = "application/json",
                            schema = @Schema(implementation = InstituicaoUsuarioResponseDTO.class))),
            @ApiResponse(responseCode = "204", description = "Busca feita com sucesso e não a dados para retornar",
                    content = @Content),
            @ApiResponse(responseCode = "404", description = "Usuário não encontrado",
                    content = @Content)
    })
    public ResponseEntity<Page<InstituicaoUsuarioResponseDTO>> getInstituicoesByUserId(
            @PathVariable UUID user_id,
            @RequestParam(defaultValue = "0") int pagina){
        Page<InstituicaoUsuarioResponseDTO> response = instituicaoService
                .getInstituicoesByUserId(user_id, PageRequest.of(pagina, 5))
                .map(InstituicaoUsuarioMapper::toDto);
        if (response.isEmpty()){
            return ResponseEntity.status(204).build();
        }
        return ResponseEntity.status(200).body(response);
    }

    @PutMapping("/desvincular-todas-as-instituicoes/usuarios/{user_id}")
    public ResponseEntity<Void> detachAllIntituicoes(@PathVariable UUID user_id){
        instituicaoService.detachAllIntituicoes(user_id);
        return ResponseEntity.status(204).build();
    }

    @DeleteMapping("{id}")
    @Operation(summary = "Deletar uma instituição",
            description = "Deletar uma instituição por seu id.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "204", description = "Instituição deletada com sucesso",
                    content = @Content),
            @ApiResponse(responseCode = "404", description = "Instituição não encontrada",
                    content = @Content)
    })
    public ResponseEntity<Void> deleteInstituicao(@PathVariable Integer id){
        instituicaoService.deleteInstituicao(id);
        return ResponseEntity.status(204).build();
    }

    @GetMapping("/resumo/usuarios/{user_id}")
    @Operation(summary = "Cards de resumo das instituições do usuário",
            description = "Retorna um resumo de cada instituição ativa do usuário com saldo, crédito, débito, parcelamentos ativos e % de crédito utilizado. Suporta filtro por período (periodo, ano, mes, trimestre, semestre).")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", content = @Content(mediaType = "application/json",
                    schema = @Schema(implementation = ResumoInstituicaoDto.class))),
            @ApiResponse(responseCode = "204", content = @Content),
            @ApiResponse(responseCode = "404", content = @Content)
    })
    public ResponseEntity<List<ResumoInstituicaoDto>> getResumoInstituicoes(
            @PathVariable UUID user_id,
            @RequestParam(required = false) String periodo,
            @RequestParam(required = false) Integer ano,
            @RequestParam(required = false) Integer mes,
            @RequestParam(required = false) Integer trimestre,
            @RequestParam(required = false) Integer semestre) {

        LocalDate dataInicio = null;
        LocalDate dataFim = null;

        if (periodo != null && ano != null) {
            switch (periodo) {
                case "MENSAL" -> {
                    int m = mes != null ? mes : 1;
                    dataInicio = LocalDate.of(ano, m, 1);
                    dataFim = dataInicio.withDayOfMonth(dataInicio.lengthOfMonth());
                }
                case "TRIMESTRAL" -> {
                    int t = trimestre != null ? trimestre : 1;
                    int mesInicio = (t - 1) * 3 + 1;
                    dataInicio = LocalDate.of(ano, mesInicio, 1);
                    dataFim = dataInicio.plusMonths(3).minusDays(1);
                }
                case "SEMESTRAL" -> {
                    int s = semestre != null ? semestre : 1;
                    int mesInicio = (s - 1) * 6 + 1;
                    dataInicio = LocalDate.of(ano, mesInicio, 1);
                    dataFim = dataInicio.plusMonths(6).minusDays(1);
                }
                case "ANUAL" -> {
                    dataInicio = LocalDate.of(ano, 1, 1);
                    dataFim = LocalDate.of(ano, 12, 31);
                }
            }
        }

        List<ResumoInstituicaoDto> resultado = instituicaoService.getResumoInstituicoes(user_id, dataInicio, dataFim);
        return resultado.isEmpty() ? ResponseEntity.noContent().build() : ResponseEntity.ok(resultado);
    }

    @GetMapping("/{instUsuario_id}/detalhe")
    @Operation(summary = "Detalhe de uma instituição com distribuição por tipo de movimento",
            description = "Retorna os dados da associação usuário-instituição e a distribuição dos valores por tipo de movimento (débito, crédito, pix, etc).")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", content = @Content(mediaType = "application/json",
                    schema = @Schema(implementation = DetalheInstituicaoDto.class))),
            @ApiResponse(responseCode = "404", content = @Content)
    })
    public ResponseEntity<DetalheInstituicaoDto> getDetalheInstituicao(@PathVariable Integer instUsuario_id) {
        return ResponseEntity.ok(instituicaoService.getDetalheInstituicao(instUsuario_id));
    }

    @PatchMapping("/{instUsuario_id}/configurar")
    @Operation(summary = "Atualizar limite de crédito e taxa de juros da instituição",
            description = "Permite ao usuário configurar o limite de crédito disponível e a taxa de juros da instituição.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", content = @Content(mediaType = "application/json",
                    schema = @Schema(implementation = InstituicaoUsuarioResponseDTO.class))),
            @ApiResponse(responseCode = "404", content = @Content)
    })
    public ResponseEntity<InstituicaoUsuarioResponseDTO> configurarInstituicaoUsuario(
            @PathVariable Integer instUsuario_id,
            @RequestBody AtualizarInstituicaoUsuarioDto dto) {
        InstituicaoUsuario updated = instituicaoService.atualizarInstituicaoUsuario(instUsuario_id, dto);
        return ResponseEntity.ok(InstituicaoUsuarioMapper.toDto(updated));
    }

    @PostMapping("/{instUsuario_id}/pagar-fatura")
    @Operation(summary = "Pagar fatura do cartão de crédito",
            description = "Registra o pagamento de fatura, liberando crédito disponível.")
    @ApiResponses(value = {
            @ApiResponse(responseCode = "200", description = "Pagamento registrado."),
            @ApiResponse(responseCode = "400", description = "Valor inválido.", content = @Content),
            @ApiResponse(responseCode = "404", content = @Content)
    })
    public ResponseEntity<?> pagarFatura(
            @PathVariable Integer instUsuario_id,
            @RequestBody java.util.Map<String, Double> body) {
        Double valor = body.get("valor");
        if (valor == null || valor <= 0) {
            return ResponseEntity.badRequest().body("Informe um valor válido.");
        }
        instituicaoService.pagarFatura(instUsuario_id, java.math.BigDecimal.valueOf(valor));
        return ResponseEntity.ok().build();
    }
}

package controle.api.back_end.controller;

import controle.api.back_end.dto.instituicao.in.AtualizarInstituicaoUsuarioDto;
import controle.api.back_end.dto.instituicao.in.InstituicaoCreateDTO;
import controle.api.back_end.dto.instituicao.out.DetalheInstituicaoDto;
import controle.api.back_end.dto.instituicao.out.InstituicaoResponseDTO;
