        },
        // ── PASSO 1: anos com registros ─────────────────────────────
        buscarAnosRegistros(userId) {
            return request(`/registros/anos/usuarios/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        // ── PASSO 2: meses (do ano) com registros ───────────────────
        buscarMesesRegistros(userId, ano) {
            return request(`/registros/meses/usuarios/${userId}?ano=${ano}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        // ── PASSO 3: registros do mês, paginados ────────────────────
        buscarRegistrosPorMes(userId, ano, mes, pagina = 0, tamanho = 20) {
            return request(`/registros/mes/usuarios/${userId}?ano=${ano}&mes=${mes}&pagina=${pagina}&tamanho=${tamanho}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) {
                        return { content: [], totalElements: 0, totalPages: 0, number: 0, size: tamanho, first: true, last: true, empty: true };
                    }
                    return res.json();
                });
        },
        filtrarRegistros(userId, filtros) {
            const params = new URLSearchParams();

            if (filtros.valor) params.append("valor", filtros.valor);
            if (filtros.dataEvento) params.append("dataEvento", filtros.dataEvento);
            if (filtros.descricao) params.append("descricao", filtros.descricao);
            if (filtros.titulo) params.append("titulo", filtros.titulo);

            (filtros.tipo || []).forEach(v => params.append("tipo", v));
            (filtros.tipoMovimento || []).forEach(v => params.append("tipoMovimento", v));
            (filtros.instituicaoUsuario || []).forEach(v => params.append("instituicaoUsuario", v));
            (filtros.categoriaUsuario || []).forEach(v => params.append("categoriaUsuario", v));

            const query = params.toString();
            const path = query
                ? `/registros/filtro/usuarios/${userId}?${query}`
                : `/registros/filtro/usuarios/${userId}`;

            return request(path, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        adicionarTipo(payload, userId) {
            return postJson(`/categorias/usuario/${userId}`, { titulo: payload.titulo });
        },
        getTodasInstituicoes() {
            return fetchTodasPaginas("/instituicoes");
        },
        getTodasCategorias() {
            return fetchTodasPaginas("/categorias");
        },
        criarInstituicao(nome) {
            return postJson("/instituicoes", { nome });
        },
        vincularInstituicaoUsuario(instituicaoId, userId) {
            return request(`/instituicoes/${instituicaoId}/usuarios/${userId}`, { method: "POST" });
        },
        vincularCategoriaUsuario(categoriaId, userId) {
            return request(`/categorias/${categoriaId}/usuarios/${userId}`, { method: "POST" });
        },
        buscarRegistrosPorData(userId, dataSelecionada) {
            return request(`/registros/${userId}`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                })
                .then(registros => registros.filter(r => {
                    const dataEvento = r.eventoFinanceiro && r.eventoFinanceiro.dataEvento;
                    return dataEvento === dataSelecionada;
                }));
        },
        mostrarSaldoTotal(userId) {
            return request(`/registros/usuario/${userId}/saldo`, { method: "GET" })
                .then(res => res.json())
                .then(data => [{ valorTotal: data.valorTotal }]);
        },
        mostrarTodasInstituicoes(userId) {
            return request(`/registros/usuario/${userId}/saldo/instituicoes`, { method: "GET" })
                .then(res => {
                    if (res.status === 204) return [];
                    return res.json();
                });
        },
        cadastrarUsuario(payload) {
            return postJson("/usuarios", payload);
        },
        loginUsuario(payload) {
            return postJson("/usuarios/login", payload);
        },
        obterUsuario(userId) {
            return request(`/usuarios/${userId}`, { method: "GET" })
                .then(res => res.json());
        },
        enviarImagemUsuario(userId, file) {
            const formData = new FormData();
            formData.append("file", file);
            return request(`/usuarios/${userId}/upload-imagem`, {
                method: "PUT",
                body: formData
            });
        },
        salvarImagemLocal(userId, dataUrl) {
            const chave = chaveImagemLocal(userId);
            if (!chave || !dataUrl) return;
            try {
                localStorage.setItem(chave, dataUrl);
            } catch (_) {
            }
        },
        obterImagemLocal(userId) {
            const chave = chaveImagemLocal(userId);
            if (!chave) return null;
            return localStorage.getItem(chave);
        },
        resolverUrlImagem(caminhoImagem, userId) {
            // Tenta cache local primeiro (data URL)
            const local = this.obterImagemLocal(userId);
            if (local) return local;

            if (!caminhoImagem) return null;
            if (/^data:image\//i.test(caminhoImagem)) return caminhoImagem;
            if (/^https?:\/\//i.test(caminhoImagem)) return caminhoImagem;

            // Caminho relativo do servidor – constrói URL completa
            if (typeof caminhoImagem === "string" && caminhoImagem.trim()) {
                const path = caminhoImagem.startsWith("/") ? caminhoImagem : "/" + caminhoImagem;
                return `${LOCAL_API}${path}`;
            }

            return null;
        },
        editarRegistro(eventoId, payload) {
            return request(`/registros/${eventoId}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload)
            });
        },
        editarSenhaUsuario(userId, payload) {
            return request(`/usuarios/editar-senha/${userId}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload)
            });
        },
        excluirUsuario(userId) {
            return request(`/usuarios/${userId}`, { method: "DELETE" });
        },
        desvincularTodasInstituicoes(userId) {
            return request(`/instituicoes/desvincular-todas-as-instituicoes/usuarios/${userId}`, { method: "PUT" });
        },
        deletarTodosEventos(userId) {
            return request(`/configuracoes/usuarios/${userId}/dados/deletar-tudo`, { method: "DELETE" });
        },
        deletarRegistro(eventoId) {
            return request(`/registros/${eventoId}`, { method: "DELETE" });
        }
    };
})();

/* ═══════════════════════════════════════════════════════════════
   caixinhas.css — Tela de Poupança / Caixinhas
   ═══════════════════════════════════════════════════════════════ */

/* ── Page header ─────────────────────────────────────────── */
.cxh-page-header {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
    flex-wrap: wrap;
    gap: 12px;
}
.cxh-page-header h1 { margin-bottom: 0; }

.cxh-header-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cxh-header-subtitle {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    font-weight: 400;
}

.btn-nova-caixinha {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.18s, transform 0.15s;
    text-decoration: none;
}
.btn-nova-caixinha:hover { opacity: 0.88; transform: translateY(-1px); }

/* ── KPI grid ────────────────────────────────────────────── */
.cxh-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}

.cxh-kpi-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid var(--cor-tinte-borda);
    transition: transform 0.18s, box-shadow 0.18s;
}
.cxh-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--sombra-card); }

.cxh-kpi-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cxh-kpi-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.cxh-kpi-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--cor-principal);
}
.cxh-kpi-valor {
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.1;
}
.cxh-kpi-sub {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
}

/* ── Barra de progresso consolidada ─────────────────────── */
.cxh-progresso-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 16px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1px solid var(--cor-tinte-borda);
    margin-bottom: 20px;
}
.cxh-progresso-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}
.cxh-progresso-label {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-progresso-pct {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-progress-track {
    height: 10px;
    background: var(--cor-tinte-suave);
    border-radius: 6px;
    overflow: hidden;
}
.cxh-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    border-radius: 6px;
    transition: width 0.5s ease;
}

/* ── Filtros / Abas ─────────────────────────────────────── */
.cxh-filtros {
    display: flex;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.cxh-filtro-btn {
    padding: 8px 18px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-secundario);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s;
}
.cxh-filtro-btn:hover {
    background: var(--cor-tinte-suave);
    color: var(--cor-titulo);
}
.cxh-filtro-btn.ativo {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border-color: var(--cor-principal);
}

/* ── Grid de cards ──────────────────────────────────────── */
.cxh-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

/* ── Card individual de caixinha ────────────────────────── */
.cxh-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1.5px solid var(--cor-tinte-borda);
    cursor: pointer;
    transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative;
    overflow: hidden;
}
.cxh-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px var(--sombra-card);
    border-color: var(--cor-principal);
}
.cxh-card.encerrada {
    opacity: 0.72;
}
.cxh-card.encerrada::after {
    content: "ENCERRADA";
    position: absolute;
    top: 12px;
    right: -22px;
    background: var(--cor-texto-secundario);
    color: #fff;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    padding: 3px 30px;
    transform: rotate(45deg);
}

.cxh-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}
.cxh-card-nome {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.3;
}
.cxh-card-desc {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
    margin-top: 2px;
}

/* Badge de tipo de rendimento */
.cxh-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 12px;
    white-space: nowrap;
    letter-spacing: 0.04em;
}
.cxh-badge-CDI       { background: rgba(54,115,115,0.12);  color: var(--cor-principal); }
.cxh-badge-SELIC     { background: rgba(59,130,246,0.12);  color: #3B82F6; }
.cxh-badge-POUPANCA  { background: rgba(16,185,129,0.12);  color: #10B981; }
.cxh-badge-PREFIXADO { background: rgba(139,92,246,0.12);  color: #8B5CF6; }
.cxh-badge-PERSONALIZADO { background: rgba(245,158,11,0.12); color: #F59E0B; }

/* Valores */
.cxh-card-valores {
    display: flex;
    align-items: baseline;
    gap: 6px;
}
.cxh-card-valor-atual {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-card-meta {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
}

/* Barra de progresso do card */
.cxh-card-progress-track {
    height: 7px;
    background: var(--cor-tinte-suave);
    border-radius: 4px;
    overflow: hidden;
}
.cxh-card-progress-fill {
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    transition: width 0.5s ease;
}
.cxh-card-progress-fill.atingida {
    background: linear-gradient(90deg, var(--green-700), #22c55e);
}

.cxh-card-progress-info {
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-pct { font-weight: 700; color: var(--cor-titulo); }

/* Footer do card */
.cxh-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 8px;
    border-top: 1px solid var(--cor-tinte-suave);
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-meta-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--green-700);
}
.cxh-card-meta-alcancavel.nao { color: var(--red-700); }

/* ── Estado vazio ────────────────────────────────────────── */
.cxh-vazio {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 60px 20px;
    color: var(--cor-texto-secundario);
    text-align: center;
}
.cxh-vazio i { font-size: 3rem; opacity: 0.4; }
.cxh-vazio h3 { font-size: 1.1rem; color: var(--cor-titulo); }
.cxh-vazio p { font-size: 0.88rem; }

/* Loading */
.cxh-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 40px;
    color: var(--cor-texto-secundario);
    font-size: 0.95rem;
}

/* ── Insight card ─────────────────────────────────────────── */
.cxh-insight {
    background: var(--cor-tinte-suave);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 12px;
    padding: 14px 18px;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 24px;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.55;
}
.cxh-insight i {
    font-size: 1.3rem;
    color: var(--cor-principal);
    flex-shrink: 0;
    margin-top: 1px;
}

/* ═══════════════════════════════════════════════════════════════
   MODAL BASE
   ═══════════════════════════════════════════════════════════════ */
.cxh-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 9000;
    background: var(--cor-overlay);
    backdrop-filter: blur(3px);
    align-items: center;
    justify-content: center;
    padding: 16px;
}
.cxh-modal-overlay.aberto { display: flex; }

.cxh-modal {
    background: var(--cor-fundo-card);
    border-radius: 20px;
    box-shadow: 0 20px 60px var(--sombra-caixa);
    width: 100%;
    max-width: 580px;
    max-height: 90vh;
    overflow-y: auto;
    animation: cxhModalIn 0.22s ease;
    display: flex;
    flex-direction: column;
}
.cxh-modal-lg { max-width: 720px; }

@keyframes cxhModalIn {
    from { opacity: 0; transform: scale(0.93) translateY(14px); }
    to   { opacity: 1; transform: scale(1)    translateY(0); }
}

.cxh-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px 24px 16px;
    border-bottom: 1px solid var(--cor-tinte-borda);
    flex-shrink: 0;
}
.cxh-modal-header h2 {
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}
.cxh-modal-close {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: none;
    background: var(--cor-tinte-suave);
    color: var(--cor-texto-secundario);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: background 0.15s;
    padding: 0;
    margin: 0;
}
.cxh-modal-close:hover { background: var(--cor-tinte-medio); }

.cxh-modal-body {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    flex: 1;
}

.cxh-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid var(--cor-tinte-borda);
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* ── Seções do modal de criação ──────────────────────────── */
.cxh-secao-titulo {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--cor-principal);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-secao-titulo::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--cor-tinte-borda);
}

/* ── Campos de formulário ─────────────────────────────────── */
.cxh-campo-wrap {
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.cxh-campo-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-campo-input {
    padding: 10px 12px;
    border-radius: 9px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-campo);
    color: var(--cor-texto-principal);
    font-size: 0.9rem;
    width: 100%;
    transition: border-color 0.15s;
    outline: none;
}
.cxh-campo-input:focus {
    border-color: var(--cor-principal);
    background: var(--cor-fundo-card);
}
.cxh-campo-input::placeholder { color: var(--cor-texto-secundario); opacity: 0.6; }

.cxh-campo-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

/* ── Tipo de rendimento – botões inline ──────────────────── */
.cxh-rendimento-btns {
    display: flex;
    gap: 7px;
    flex-wrap: wrap;
    margin-bottom: 14px;
}
.cxh-rend-btn {
    padding: 7px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    color: var(--cor-texto-secundario);
    margin: 0;
}
.cxh-rend-btn:hover { background: var(--cor-tinte-suave); }
.cxh-rend-btn.ativo-CDI       { background: rgba(54,115,115,0.14);  color: var(--cor-principal); border-color: var(--cor-principal); }
.cxh-rend-btn.ativo-SELIC     { background: rgba(59,130,246,0.14);  color: #3B82F6;  border-color: #3B82F6; }
.cxh-rend-btn.ativo-POUPANCA  { background: rgba(16,185,129,0.14);  color: #10B981;  border-color: #10B981; }
.cxh-rend-btn.ativo-PREFIXADO { background: rgba(139,92,246,0.14);  color: #8B5CF6;  border-color: #8B5CF6; }
.cxh-rend-btn.ativo-PERSONALIZADO { background: rgba(245,158,11,0.14); color: #F59E0B; border-color: #F59E0B; }

/* Campos condicionais de rendimento */
.cxh-rend-campos { display: none; }
.cxh-rend-campos.visivel { display: flex; flex-direction: column; gap: 10px; }

/* Linha resumo taxa efetiva */
.cxh-taxa-resumo {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    background: var(--cor-tinte-suave);
    border-radius: 7px;
    padding: 7px 11px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-taxa-resumo strong { color: var(--cor-titulo); }

/* ── Seleção de Instituições ─────────────────────────────── */
.cxh-inst-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    max-height: 160px;
    overflow-y: auto;
    padding: 4px 2px;
}
.cxh-inst-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 7px 12px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    transition: all 0.15s;
    user-select: none;
}
.cxh-inst-item:hover { background: var(--cor-tinte-suave); }
.cxh-inst-item.selecionada {
    background: var(--cor-tinte-medio);
    border-color: var(--cor-principal);
    color: var(--cor-titulo);
}
.cxh-inst-item input[type="checkbox"] { display: none; }
.cxh-inst-check {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 0.65rem;
    color: transparent;
}
.cxh-inst-item.selecionada .cxh-inst-check {
    background: var(--cor-principal);
    border-color: var(--cor-principal);
    color: #fff;
}

/* ── Botões do modal ─────────────────────────────────────── */
.btn-cxh-salvar {
    padding: 10px 22px;
    border-radius: 10px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    transition: opacity 0.18s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-salvar:hover:not(:disabled) { opacity: 0.85; }
.btn-cxh-salvar:disabled { opacity: 0.45; cursor: not-allowed; }

.btn-cxh-cancelar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-texto-secundario);
    border: 1.5px solid var(--cor-tinte-borda);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-cancelar:hover { background: var(--cor-tinte-suave); }

.btn-cxh-encerrar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: #F59E0B;
    border: 1.5px solid #F59E0B;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-encerrar:hover { background: rgba(245,158,11,0.1); }

.btn-cxh-deletar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--red-700);
    border: 1.5px solid var(--red-700);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-deletar:hover { background: var(--red-100); }

.btn-cxh-editar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-acao-editar);
    border: 1.5px solid var(--cor-acao-editar);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-editar:hover { background: var(--cor-acao-editar-suave); }

/* ═══════════════════════════════════════════════════════════════
   MODAL DE DETALHES
   ═══════════════════════════════════════════════════════════════ */
.cxh-det-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.cxh-det-stat {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.cxh-det-stat-label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--cor-texto-secundario);
}
.cxh-det-stat-val {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-det-stat-val.positivo { color: var(--green-700); }
.cxh-det-stat-val.negativo { color: var(--red-700); }

.cxh-det-projecao {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 14px;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    line-height: 1.65;
    border: 1px solid var(--cor-tinte-borda);
}
.cxh-det-projecao strong { color: var(--cor-titulo); }

.cxh-det-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 20px;
    font-size: 0.82rem;
    font-weight: 700;
    background: var(--green-100);
    color: var(--green-700);
}
.cxh-det-alcancavel.nao {
    background: var(--red-100);
    color: var(--red-700);
}

/* Instituições no detalhe */
.cxh-det-inst-lista {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.cxh-det-inst-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 12px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    font-size: 0.82rem;
}
.cxh-det-inst-nome { font-weight: 600; color: var(--cor-titulo); }
.cxh-det-inst-val { color: var(--cor-texto-secundario); }

/* ── Feedback / Toast ─────────────────────────────────────── */
.cxh-toast {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 18px;
    border-radius: 12px;
    font-size: 0.88rem;
    font-weight: 600;
    background: var(--cor-fundo-card);
    box-shadow: 0 6px 24px var(--sombra-caixa);
    border: 1px solid var(--cor-tinte-borda);
    animation: cxhToastIn 0.22s ease;
    max-width: 340px;
}
.cxh-toast.sucesso { border-color: var(--green-700); color: var(--green-700); }
.cxh-toast.erro    { border-color: var(--red-700);   color: var(--red-700);   }

@keyframes cxhToastIn {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Responsivo ──────────────────────────────────────────── */
@media (max-width: 600px) {
    .cxh-campo-row { grid-template-columns: 1fr; }
    .cxh-det-grid  { grid-template-columns: 1fr; }
    .cxh-modal-footer { flex-direction: column; }
    .cxh-modal-footer button { width: 100%; justify-content: center; }
    .cxh-rendimento-btns { gap: 5px; }
    .cxh-rend-btn { font-size: 0.72rem; padding: 6px 10px; }
}

/* ═══════════════════════════════════════════════════════════════
   caixinhas.css — Tela de Poupança / Caixinhas
   ═══════════════════════════════════════════════════════════════ */

/* ── Page header ─────────────────────────────────────────── */
.cxh-page-header {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 8px;
    flex-wrap: wrap;
    gap: 12px;
}
.cxh-page-header h1 { margin-bottom: 0; }

.cxh-header-left {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.cxh-header-subtitle {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    font-weight: 400;
}

.btn-nova-caixinha {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    padding: 10px 20px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.18s, transform 0.15s;
    text-decoration: none;
}
.btn-nova-caixinha:hover { opacity: 0.88; transform: translateY(-1px); }

/* ── KPI grid ────────────────────────────────────────────── */
.cxh-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 20px;
}

.cxh-kpi-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 18px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    display: flex;
    flex-direction: column;
    gap: 6px;
    border: 1px solid var(--cor-tinte-borda);
    transition: transform 0.18s, box-shadow 0.18s;
}
.cxh-kpi-card:hover { transform: translateY(-2px); box-shadow: 0 6px 20px var(--sombra-card); }

.cxh-kpi-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}
.cxh-kpi-label {
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.cxh-kpi-icon {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    color: var(--cor-principal);
}
.cxh-kpi-valor {
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.1;
}
.cxh-kpi-sub {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
}

/* ── Barra de progresso consolidada ─────────────────────── */
.cxh-progresso-card {
    background: var(--cor-fundo-card);
    border-radius: 14px;
    padding: 16px 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1px solid var(--cor-tinte-borda);
    margin-bottom: 20px;
}
.cxh-progresso-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
}
.cxh-progresso-label {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-progresso-pct {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-progress-track {
    height: 10px;
    background: var(--cor-tinte-suave);
    border-radius: 6px;
    overflow: hidden;
}
.cxh-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    border-radius: 6px;
    transition: width 0.5s ease;
}

/* ── Filtros / Abas ─────────────────────────────────────── */
.cxh-filtros {
    display: flex;
    gap: 8px;
    margin-bottom: 20px;
    flex-wrap: wrap;
}
.cxh-filtro-btn {
    padding: 8px 18px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-secundario);
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.18s;
}
.cxh-filtro-btn:hover {
    background: var(--cor-tinte-suave);
    color: var(--cor-titulo);
}
.cxh-filtro-btn.ativo {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border-color: var(--cor-principal);
}

/* ── Grid de cards ──────────────────────────────────────── */
.cxh-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

/* ── Card individual de caixinha ────────────────────────── */
.cxh-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 2px 12px var(--sombra-card);
    border: 1.5px solid var(--cor-tinte-borda);
    cursor: pointer;
    transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative;
    overflow: hidden;
}
.cxh-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px var(--sombra-card);
    border-color: var(--cor-principal);
}
.cxh-card.encerrada {
    opacity: 0.72;
}
.cxh-card.encerrada::after {
    content: "ENCERRADA";
    position: absolute;
    top: 12px;
    right: -22px;
    background: var(--cor-texto-secundario);
    color: #fff;
    font-size: 0.62rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    padding: 3px 30px;
    transform: rotate(45deg);
}

.cxh-card-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}
.cxh-card-nome {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    line-height: 1.3;
}
.cxh-card-desc {
    font-size: 0.78rem;
    color: var(--cor-texto-secundario);
    margin-top: 2px;
}

/* Badge de tipo de rendimento */
.cxh-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 12px;
    white-space: nowrap;
    letter-spacing: 0.04em;
}
.cxh-badge-CDI       { background: rgba(54,115,115,0.12);  color: var(--cor-principal); }
.cxh-badge-SELIC     { background: rgba(59,130,246,0.12);  color: #3B82F6; }
.cxh-badge-POUPANCA  { background: rgba(16,185,129,0.12);  color: #10B981; }
.cxh-badge-PREFIXADO { background: rgba(139,92,246,0.12);  color: #8B5CF6; }
.cxh-badge-PERSONALIZADO { background: rgba(245,158,11,0.12); color: #F59E0B; }

/* Valores */
.cxh-card-valores {
    display: flex;
    align-items: baseline;
    gap: 6px;
}
.cxh-card-valor-atual {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-card-meta {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
}

/* Barra de progresso do card */
.cxh-card-progress-track {
    height: 7px;
    background: var(--cor-tinte-suave);
    border-radius: 4px;
    overflow: hidden;
}
.cxh-card-progress-fill {
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--cor-principal), var(--cor-titulo));
    transition: width 0.5s ease;
}
.cxh-card-progress-fill.atingida {
    background: linear-gradient(90deg, var(--green-700), #22c55e);
}

.cxh-card-progress-info {
    display: flex;
    justify-content: space-between;
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-pct { font-weight: 700; color: var(--cor-titulo); }

/* Footer do card */
.cxh-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 8px;
    border-top: 1px solid var(--cor-tinte-suave);
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
}
.cxh-card-meta-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--green-700);
}
.cxh-card-meta-alcancavel.nao { color: var(--red-700); }

/* ── Estado vazio ────────────────────────────────────────── */
.cxh-vazio {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    padding: 60px 20px;
    color: var(--cor-texto-secundario);
    text-align: center;
}
.cxh-vazio i { font-size: 3rem; opacity: 0.4; }
.cxh-vazio h3 { font-size: 1.1rem; color: var(--cor-titulo); }
.cxh-vazio p { font-size: 0.88rem; }

/* Loading */
.cxh-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 40px;
    color: var(--cor-texto-secundario);
    font-size: 0.95rem;
}

/* ── Insight card ─────────────────────────────────────────── */
.cxh-insight {
    background: var(--cor-tinte-suave);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 12px;
    padding: 14px 18px;
    display: flex;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 24px;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.55;
}
.cxh-insight i {
    font-size: 1.3rem;
    color: var(--cor-principal);
    flex-shrink: 0;
    margin-top: 1px;
}

/* ═══════════════════════════════════════════════════════════════
   MODAL BASE
   ═══════════════════════════════════════════════════════════════ */
.cxh-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 9000;
    background: var(--cor-overlay);
    backdrop-filter: blur(3px);
    align-items: center;
    justify-content: center;
    padding: 16px;
}
.cxh-modal-overlay.aberto { display: flex; }

.cxh-modal {
    background: var(--cor-fundo-card);
    border-radius: 20px;
    box-shadow: 0 20px 60px var(--sombra-caixa);
    width: 100%;
    max-width: 580px;
    max-height: 90vh;
    overflow-y: auto;
    animation: cxhModalIn 0.22s ease;
    display: flex;
    flex-direction: column;
}
.cxh-modal-lg { max-width: 720px; }

@keyframes cxhModalIn {
    from { opacity: 0; transform: scale(0.93) translateY(14px); }
    to   { opacity: 1; transform: scale(1)    translateY(0); }
}

.cxh-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 22px 24px 16px;
    border-bottom: 1px solid var(--cor-tinte-borda);
    flex-shrink: 0;
}
.cxh-modal-header h2 {
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}
.cxh-modal-close {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    border: none;
    background: var(--cor-tinte-suave);
    color: var(--cor-texto-secundario);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: background 0.15s;
    padding: 0;
    margin: 0;
}
.cxh-modal-close:hover { background: var(--cor-tinte-medio); }

.cxh-modal-body {
    padding: 20px 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    flex: 1;
}

.cxh-modal-footer {
    padding: 16px 24px;
    border-top: 1px solid var(--cor-tinte-borda);
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    flex-shrink: 0;
}

/* ── Seções do modal de criação ──────────────────────────── */
.cxh-secao-titulo {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--cor-principal);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-secao-titulo::after {
    content: "";
    flex: 1;
    height: 1px;
    background: var(--cor-tinte-borda);
}

/* ── Campos de formulário ─────────────────────────────────── */
.cxh-campo-wrap {
    display: flex;
    flex-direction: column;
    gap: 5px;
}
.cxh-campo-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
}
.cxh-campo-input {
    padding: 10px 12px;
    border-radius: 9px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-campo);
    color: var(--cor-texto-principal);
    font-size: 0.9rem;
    width: 100%;
    transition: border-color 0.15s;
    outline: none;
}
.cxh-campo-input:focus {
    border-color: var(--cor-principal);
    background: var(--cor-fundo-card);
}
.cxh-campo-input::placeholder { color: var(--cor-texto-secundario); opacity: 0.6; }

.cxh-campo-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

/* ── Tipo de rendimento – botões inline ──────────────────── */
.cxh-rendimento-btns {
    display: flex;
    gap: 7px;
    flex-wrap: wrap;
    margin-bottom: 14px;
}
.cxh-rend-btn {
    padding: 7px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    color: var(--cor-texto-secundario);
    margin: 0;
}
.cxh-rend-btn:hover { background: var(--cor-tinte-suave); }
.cxh-rend-btn.ativo-CDI       { background: rgba(54,115,115,0.14);  color: var(--cor-principal); border-color: var(--cor-principal); }
.cxh-rend-btn.ativo-SELIC     { background: rgba(59,130,246,0.14);  color: #3B82F6;  border-color: #3B82F6; }
.cxh-rend-btn.ativo-POUPANCA  { background: rgba(16,185,129,0.14);  color: #10B981;  border-color: #10B981; }
.cxh-rend-btn.ativo-PREFIXADO { background: rgba(139,92,246,0.14);  color: #8B5CF6;  border-color: #8B5CF6; }
.cxh-rend-btn.ativo-PERSONALIZADO { background: rgba(245,158,11,0.14); color: #F59E0B; border-color: #F59E0B; }

/* Campos condicionais de rendimento */
.cxh-rend-campos { display: none; }
.cxh-rend-campos.visivel { display: flex; flex-direction: column; gap: 10px; }

/* Linha resumo taxa efetiva */
.cxh-taxa-resumo {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    background: var(--cor-tinte-suave);
    border-radius: 7px;
    padding: 7px 11px;
    display: flex;
    align-items: center;
    gap: 6px;
}
.cxh-taxa-resumo strong { color: var(--cor-titulo); }

/* ── Seleção de Instituições ─────────────────────────────── */
.cxh-inst-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    max-height: 160px;
    overflow-y: auto;
    padding: 4px 2px;
}
.cxh-inst-item {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 7px 12px;
    border-radius: 20px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    cursor: pointer;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    transition: all 0.15s;
    user-select: none;
}
.cxh-inst-item:hover { background: var(--cor-tinte-suave); }
.cxh-inst-item.selecionada {
    background: var(--cor-tinte-medio);
    border-color: var(--cor-principal);
    color: var(--cor-titulo);
}
.cxh-inst-item input[type="checkbox"] { display: none; }
.cxh-inst-check {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: 1.5px solid var(--cor-tinte-borda);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 0.65rem;
    color: transparent;
}
.cxh-inst-item.selecionada .cxh-inst-check {
    background: var(--cor-principal);
    border-color: var(--cor-principal);
    color: #fff;
}

/* ── Botões do modal ─────────────────────────────────────── */
.btn-cxh-salvar {
    padding: 10px 22px;
    border-radius: 10px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    transition: opacity 0.18s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-salvar:hover:not(:disabled) { opacity: 0.85; }
.btn-cxh-salvar:disabled { opacity: 0.45; cursor: not-allowed; }

.btn-cxh-cancelar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-texto-secundario);
    border: 1.5px solid var(--cor-tinte-borda);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin: 0;
}
.btn-cxh-cancelar:hover { background: var(--cor-tinte-suave); }

.btn-cxh-encerrar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: #F59E0B;
    border: 1.5px solid #F59E0B;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-encerrar:hover { background: rgba(245,158,11,0.1); }

.btn-cxh-deletar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--red-700);
    border: 1.5px solid var(--red-700);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-deletar:hover { background: var(--red-100); }

.btn-cxh-editar {
    padding: 10px 18px;
    border-radius: 10px;
    background: transparent;
    color: var(--cor-acao-editar);
    border: 1.5px solid var(--cor-acao-editar);
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin: 0;
}
.btn-cxh-editar:hover { background: var(--cor-acao-editar-suave); }

.btn-cxh-reabrir {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 9px 18px; border: 1.5px solid #059669; border-radius: 8px;
    background: transparent; color: #059669;
    font-size: 0.88rem; font-weight: 600; cursor: pointer; transition: background 0.15s;
}
.btn-cxh-reabrir:hover { background: rgba(5,150,105,0.08); }

.btn-cxh-reabrir-confirmar {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 9px 18px; border: none; border-radius: 8px;
    background: #059669; color: #fff;
    font-size: 0.88rem; font-weight: 600; cursor: pointer; transition: opacity 0.15s;
}
.btn-cxh-reabrir-confirmar:hover { opacity: 0.85; }

/* Footer de confirmação inline */
.cxh-footer-confirmacao {
    background: var(--cor-tinte-suave);
    border-top: 1px solid var(--cor-tinte-borda);
    border-radius: 0 0 16px 16px;
    animation: fadeIn 0.15s ease;
    gap: 10px;
    align-items: center;
}

.btn-cxh-encerrar-confirmar,
.btn-cxh-deletar-confirmar {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 9px 18px;
    border: none;
    border-radius: 8px;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.15s;
}

.btn-cxh-encerrar-confirmar {
    background: #f59e0b;
    color: #fff;
}
.btn-cxh-encerrar-confirmar:hover { opacity: 0.85; }

.btn-cxh-deletar-confirmar {
    background: var(--red-600, #dc2626);
    color: #fff;
}
.btn-cxh-deletar-confirmar:hover { opacity: 0.85; }


   MODAL DE DETALHES
   ═══════════════════════════════════════════════════════════════ */
.cxh-det-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.cxh-det-stat {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 3px;
}
.cxh-det-stat-label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--cor-texto-secundario);
}
.cxh-det-stat-val {
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--cor-titulo);
}
.cxh-det-stat-val.positivo { color: var(--green-700); }
.cxh-det-stat-val.negativo { color: var(--red-700); }

.cxh-det-projecao {
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 14px;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    line-height: 1.65;
    border: 1px solid var(--cor-tinte-borda);
}
.cxh-det-projecao strong { color: var(--cor-titulo); }

.cxh-det-alcancavel {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 20px;
    font-size: 0.82rem;
    font-weight: 700;
    background: var(--green-100);
    color: var(--green-700);
}
.cxh-det-alcancavel.nao {
    background: var(--red-100);
    color: var(--red-700);
}

/* Instituições no detalhe */
.cxh-det-inst-lista {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.cxh-det-inst-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 12px;
    border-radius: 8px;
    background: var(--cor-tinte-suave);
    font-size: 0.82rem;
}
.cxh-det-inst-nome { font-weight: 600; color: var(--cor-titulo); }
.cxh-det-inst-val { color: var(--cor-texto-secundario); }

/* ── Feedback / Toast ─────────────────────────────────────── */
.cxh-toast {
    position: fixed;
    bottom: 28px;
    right: 28px;
    z-index: 99999;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 18px;
    border-radius: 12px;
    font-size: 0.88rem;
    font-weight: 600;
    background: var(--cor-fundo-card);
    box-shadow: 0 6px 24px var(--sombra-caixa);
    border: 1px solid var(--cor-tinte-borda);
    animation: cxhToastIn 0.22s ease;
    max-width: 340px;
}
.cxh-toast.sucesso { border-color: var(--green-700); color: var(--green-700); }
.cxh-toast.erro    { border-color: var(--red-700);   color: var(--red-700);   }

@keyframes cxhToastIn {
    from { opacity: 0; transform: translateY(16px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── Responsivo ──────────────────────────────────────────── */
@media (max-width: 600px) {
    .cxh-campo-row { grid-template-columns: 1fr; }
    .cxh-det-grid  { grid-template-columns: 1fr; }
    .cxh-modal-footer { flex-direction: column; }
    .cxh-modal-footer button { width: 100%; justify-content: center; }
    .cxh-rendimento-btns { gap: 5px; }
    .cxh-rend-btn { font-size: 0.72rem; padding: 6px 10px; }
}

/* ============================================================================
   EMPRÉSTIMOS - Estilos
   ============================================================================ */

.emprestimos-resumo-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.emprestimo-resumo-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    display: flex;
    align-items: center;
    gap: 1.25rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.emprestimo-resumo-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-resumo-card.receber .resumo-icon {
    background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}

.emprestimo-resumo-card.pagar .resumo-icon {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
}

.resumo-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 1.8rem;
    flex-shrink: 0;
}

.resumo-info {
    flex: 1;
}

.resumo-label {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    margin: 0 0 0.25rem 0;
    font-weight: 500;
}

.resumo-valor {
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.resumo-detalhes {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    margin: 0;
}

/* ── Ações e Filtros ── */
.emprestimos-acoes {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

.filtros-emprestimo {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-filtro {
    padding: 0.5rem 1rem;
    border: 2px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-principal);
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-filtro:hover {
    background: var(--cor-hover);
    border-color: var(--cor-principal);
}

.btn-filtro.ativo {
    background: var(--cor-principal);
    color: #fff;
    border-color: var(--cor-principal);
}

/* ── Lista de Empréstimos ── */
.emprestimos-lista {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.emprestimo-item {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    border-left: 4px solid;
}

.emprestimo-item.emprestei {
    border-left-color: #10b981;
}

.emprestimo-item.pedi-emprestado {
    border-left-color: #ef4444;
}

.emprestimo-item.quitado {
    opacity: 0.7;
    border-left-color: #6b7280;
}

.emprestimo-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1rem;
}

.emprestimo-info {
    flex: 1;
}

.emprestimo-tipo {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.emprestimo-tipo.emprestei {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-tipo.pedi-emprestado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-pessoa {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.emprestimo-data {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.emprestimo-status {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.9rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
}

.emprestimo-status.pendente {
    background: #fef3c7;
    color: #92400e;
}

.emprestimo-status.pago-parcial {
    background: #dbeafe;
    color: #1e40af;
}

.emprestimo-status.quitado {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-status.atrasado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-valores {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 1rem;
    margin-bottom: 1rem;
}

.emprestimo-valor-item {
    display: flex;
    flex-direction: column;
}

.emprestimo-valor-label {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.emprestimo-valor-numero {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}

.emprestimo-progresso {
    margin-bottom: 1rem;
}

.progresso-bar-container {
    width: 100%;
    height: 8px;
    background: var(--cor-fundo-pagina);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.progresso-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal) 0%, var(--cor-hover) 100%);
    border-radius: 4px;
    transition: width 0.3s ease;
}

.progresso-texto {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    text-align: right;
}

.emprestimo-observacoes {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 0.75rem;
    margin-bottom: 1rem;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.5;
}

.emprestimo-acoes-item {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-acao {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: all 0.2s ease;
}

.btn-acao.registrar {
    background: #3b82f6;
    color: #fff;
}

.btn-acao.registrar:hover {
    background: #2563eb;
}

.btn-acao.quitar {
    background: #10b981;
    color: #fff;
}

.btn-acao.quitar:hover {
    background: #059669;
}

.btn-acao.editar {
    background: #f59e0b;
    color: #fff;
}

.btn-acao.editar:hover {
    background: #d97706;
}

.btn-acao.deletar {
    background: #ef4444;
    color: #fff;
}

.btn-acao.deletar:hover {
    background: #dc2626;
}

.btn-acao.reabrir {
    background: #8b5cf6;
    color: #fff;
}

.btn-acao.reabrir:hover {
    background: #7c3aed;
}

/* ── Modais ── */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    z-index: 10000;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(4px);
    animation: fadeIn 0.2s ease;
}

.modal.aberto {
    display: flex;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

.modal-content {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    max-width: 600px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3);
    animation: slideUp 0.3s ease;
}

.modal-content.modal-pequeno {
    max-width: 400px;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(40px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--cor-tinte-borda);
}

.modal-header h2 {
    margin: 0;
    font-size: 1.5rem;
    color: var(--cor-titulo);
}

.btn-fechar {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    color: var(--cor-texto-secundario);
    padding: 0;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.2s ease;
}

.btn-fechar:hover {
    background: var(--cor-hover);
    color: var(--cor-titulo);
}

.modal-body {
    padding: 1.5rem;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.info-pagamento {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    color: var(--cor-texto-secundario);
    line-height: 1.6;
}

/* ── Botões Gerais ── */
.btn-primario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-principal);
    color: #fff;
    border: none;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: all 0.2s ease;
}

.btn-primario:hover {
    opacity: 0.9;
    transform: translateY(-2px);
}

.btn-secundario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-fundo-pagina);
    color: var(--cor-texto-principal);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-secundario:hover {
    background: var(--cor-hover);
}

/* ── Estado Vazio ── */
.estado-vazio {
    text-align: center;
    padding: 4rem 2rem;
    color: var(--cor-texto-secundario);
}

.estado-vazio i {
    font-size: 4rem;
    color: var(--cor-tinte-borda);
    margin-bottom: 1rem;
}

.estado-vazio h3 {
    font-size: 1.25rem;
    color: var(--cor-titulo);
    margin: 0 0 0.5rem 0;
}

.estado-vazio p {
    font-size: 0.95rem;
    margin: 0;
}

/* ── Responsividade ── */
@media (max-width: 768px) {
    .emprestimos-acoes {
        flex-direction: column;
        align-items: stretch;
    }

    .filtros-emprestimo {
        justify-content: center;
    }

    .emprestimo-header {
        flex-direction: column;
        gap: 0.75rem;
    }

    .emprestimo-valores {
        grid-template-columns: 1fr;
    }

    .emprestimo-acoes-item {
        flex-direction: column;
    }

    .btn-acao {
        width: 100%;
        justify-content: center;
    }
}

/* ============================================================================
   EMPRÉSTIMOS - Estilos
   ============================================================================ */

/* ── Tabs (reusa .ar-tabs / .ar-tab do registro.css, mas definido aqui como fallback) ── */
.ar-tabs {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
    border-bottom: 2px solid var(--cor-tinte-borda, #e5e7eb);
    padding-bottom: 0;
}
.ar-tab {
    background: transparent;
    border: none;
    padding: 0.75rem 1.25rem;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--cor-texto-secundario);
    cursor: pointer;
    border-bottom: 3px solid transparent;
    margin-bottom: -2px;
    border-radius: 8px 8px 0 0;
    transition: color 0.2s, border-color 0.2s;
}
.ar-tab:hover { color: var(--cor-principal); }
.ar-tab.ativo { color: var(--cor-principal); border-bottom-color: var(--cor-principal); }

/* Status extra para bancários */
.emprestimo-status.ativo { background: rgba(16, 185, 129, 0.1); color: #10b981; }
.emprestimo-status.atrasado { background: rgba(239, 68, 68, 0.1); color: #ef4444; }

.emprestimos-resumo-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.emprestimo-resumo-card {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    display: flex;
    align-items: center;
    gap: 1.25rem;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.emprestimo-resumo-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-resumo-card.receber .resumo-icon {
    background: linear-gradient(135deg, #10b981 0%, #059669 100%);
}

.emprestimo-resumo-card.pagar .resumo-icon {
    background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
}

.resumo-icon {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 1.8rem;
    flex-shrink: 0;
}

.resumo-info {
    flex: 1;
}

.resumo-label {
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    margin: 0 0 0.25rem 0;
    font-weight: 500;
}

.resumo-valor {
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.resumo-detalhes {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    margin: 0;
}

/* ── Ações e Filtros ── */
.emprestimos-acoes {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 1rem;
}

.filtros-emprestimo {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-filtro {
    padding: 0.5rem 1rem;
    border: 2px solid var(--cor-tinte-borda);
    background: var(--cor-fundo-card);
    color: var(--cor-texto-principal);
    border-radius: 8px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-filtro:hover {
    background: var(--cor-hover);
    border-color: var(--cor-principal);
}

.btn-filtro.ativo {
    background: var(--cor-principal);
    color: #fff;
    border-color: var(--cor-principal);
}

/* ── Lista de Empréstimos ── */
.emprestimos-lista {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.emprestimo-item {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    padding: 1.5rem;
    box-shadow: 0 4px 16px var(--sombra-card);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
    border-left: 4px solid;
}

.emprestimo-item.emprestei {
    border-left-color: #10b981;
}

.emprestimo-item.pedi-emprestado {
    border-left-color: #ef4444;
}

.emprestimo-item.quitado {
    opacity: 0.7;
    border-left-color: #6b7280;
}

.emprestimo-item:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px var(--sombra-card);
}

.emprestimo-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 1rem;
}

.emprestimo-info {
    flex: 1;
}

.emprestimo-tipo {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.25rem 0.75rem;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.emprestimo-tipo.emprestei {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-tipo.pedi-emprestado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-pessoa {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0 0 0.25rem 0;
}

.emprestimo-data {
    font-size: 0.8rem;
    color: var(--cor-texto-secundario);
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.emprestimo-status {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.4rem 0.9rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
}

.emprestimo-status.pendente {
    background: #fef3c7;
    color: #92400e;
}

.emprestimo-status.pago-parcial {
    background: #dbeafe;
    color: #1e40af;
}

.emprestimo-status.quitado {
    background: #d1fae5;
    color: #065f46;
}

.emprestimo-status.atrasado {
    background: #fee2e2;
    color: #991b1b;
}

.emprestimo-valores {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 1rem;
    margin-bottom: 1rem;
}

.emprestimo-valor-item {
    display: flex;
    flex-direction: column;
}

.emprestimo-valor-label {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    margin-bottom: 0.25rem;
    font-weight: 500;
}

.emprestimo-valor-numero {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cor-titulo);
}

.emprestimo-progresso {
    margin-bottom: 1rem;
}

.progresso-bar-container {
    width: 100%;
    height: 8px;
    background: var(--cor-fundo-pagina);
    border-radius: 4px;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.progresso-bar {
    height: 100%;
    background: linear-gradient(90deg, var(--cor-principal) 0%, var(--cor-hover) 100%);
    border-radius: 4px;
    transition: width 0.3s ease;
}

.progresso-texto {
    font-size: 0.75rem;
    color: var(--cor-texto-secundario);
    text-align: right;
}

.emprestimo-observacoes {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 0.75rem;
    margin-bottom: 1rem;
    font-size: 0.85rem;
    color: var(--cor-texto-secundario);
    line-height: 1.5;
}

.emprestimo-acoes-item {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.btn-acao {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: all 0.2s ease;
}

.btn-acao.registrar {
    background: #3b82f6;
    color: #fff;
}

.btn-acao.registrar:hover {
    background: #2563eb;
}

.btn-acao.quitar {
    background: #10b981;
    color: #fff;
}

.btn-acao.quitar:hover {
    background: #059669;
}

.btn-acao.editar {
    background: #f59e0b;
    color: #fff;
}

.btn-acao.editar:hover {
    background: #d97706;
}

.btn-acao.deletar {
    background: #ef4444;
    color: #fff;
}

.btn-acao.deletar:hover {
    background: #dc2626;
}

.btn-acao.reabrir {
    background: #8b5cf6;
    color: #fff;
}

.btn-acao.reabrir:hover {
    background: #7c3aed;
}

/* ── Modais ── */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    z-index: 10000;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(4px);
    animation: fadeIn 0.2s ease;
}

.modal.aberto {
    display: flex;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

.modal-content {
    background: var(--cor-fundo-card);
    border-radius: 16px;
    max-width: 600px;
    width: 90%;
    max-height: 90vh;
    overflow-y: auto;
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.3);
    animation: slideUp 0.3s ease;
}

.modal-content.modal-pequeno {
    max-width: 400px;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(40px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.5rem;
    border-bottom: 1px solid var(--cor-tinte-borda);
}

.modal-header h2 {
    margin: 0;
    font-size: 1.5rem;
    color: var(--cor-titulo);
}

.btn-fechar {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    color: var(--cor-texto-secundario);
    padding: 0;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.2s ease;
}

.btn-fechar:hover {
    background: var(--cor-hover);
    color: var(--cor-titulo);
}

.modal-body {
    padding: 1.5rem;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.info-pagamento {
    background: var(--cor-fundo-pagina);
    border-radius: 8px;
    padding: 1rem;
    margin-bottom: 1rem;
    font-size: 0.9rem;
    color: var(--cor-texto-secundario);
    line-height: 1.6;
}

/* ── Botões Gerais ── */
.btn-primario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-principal);
    color: #fff;
    border: none;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    transition: all 0.2s ease;
}

.btn-primario:hover {
    opacity: 0.9;
    transform: translateY(-2px);
}

.btn-secundario {
    padding: 0.75rem 1.5rem;
    background: var(--cor-fundo-pagina);
    color: var(--cor-texto-principal);
    border: 1px solid var(--cor-tinte-borda);
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.btn-secundario:hover {
    background: var(--cor-hover);
}

/* ── Estado Vazio ── */
.estado-vazio {
    text-align: center;
    padding: 4rem 2rem;
    color: var(--cor-texto-secundario);
}

.estado-vazio i {
    font-size: 4rem;
    color: var(--cor-tinte-borda);
    margin-bottom: 1rem;
}

.estado-vazio h3 {
    font-size: 1.25rem;
    color: var(--cor-titulo);
    margin: 0 0 0.5rem 0;
}

.estado-vazio p {
    font-size: 0.95rem;
    margin: 0;
}

/* ── Campos do modal ── */
.campo input,
.campo select {
    width: 100%;
}

.campo textarea {
    width: 100%;
    padding: 10px;
    border-radius: 10px;
    border: solid 1px var(--cor-principal);
    background-color: transparent;
    color: var(--cor-texto-principal);
    resize: vertical;
    font-size: 0.95rem;
    transition: border 0.2s;
}

.campo textarea:focus {
    outline: none;
    border: solid 2px var(--cor-principal);
}

.campo textarea:focus + label,
.campo textarea:not(:placeholder-shown) + label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.campo-label-static {
    display: block;
    font-size: 0.82rem;
    color: var(--cor-texto-secundario);
    margin-bottom: 6px;
    font-weight: 500;
}

/* ── Responsividade ── */
@media (max-width: 768px) {
    .emprestimos-acoes {
        flex-direction: column;
        align-items: stretch;
    }

    .filtros-emprestimo {
        justify-content: center;
    }

    .emprestimo-header {
        flex-direction: column;
        gap: 0.75rem;
    }

    .emprestimo-valores {
        grid-template-columns: 1fr;
    }

    .emprestimo-acoes-item {
        flex-direction: column;
    }

    .btn-acao {
        width: 100%;
        justify-content: center;
    }
}

@import "root.css";

/* ── Adicionar Registros page ── */

/* ── Tab header ── */
.ar-tabs {
    display: flex;
    gap: 0;
    margin-bottom: 0;
}

.ar-tab {
    padding: 10px 28px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-titulo);
    cursor: pointer;
    background: var(--cor-fundo-card);
    border: 2px solid var(--cor-principal);
    border-bottom: none;
    border-radius: 2px 2px 0 0;
    position: relative;
    bottom: -2px;
    transition: background 0.15s;
    text-decoration: none;
    user-select: none;
}

.ar-tab.ativo {
    background: var(--cor-fundo-card);
    color: var(--cor-hover);
    z-index: 1;
}

.ar-tab:not(.ativo) {
    background: var(--cor-fundo-inativo);
    color: var(--cor-principal);
}

/* ── Main form card ── */
.ar-card {
    background: var(--cor-fundo-card);
    border-radius: 0 20px 20px 20px;
    box-shadow: 0px 4px 4px var(--sombra-caixa);
    border-left: 2px solid var(--cor-principal);
    padding: 28px 24px;
    display: flex;
    gap: 32px;
    align-items: flex-start;
    flex-wrap: wrap;
}

/* Mascot column */
.ar-mascot {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    flex-shrink: 0;
}

.ar-mascot-img {
    width: 200px;
    border: 1px solid var(--cor-borda-mascote);
    box-shadow: 0px 4px 4px var(--sombra-caixa);
    border-radius: 4px;
    display: block;
}

/* Form column */
.ar-form-col {
    flex: 1;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.formulario-adicionar-gasto {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    padding: 1rem;
}

.botao-formulario {
    display: flex;
    align-items: end;
    gap: 1rem;
}

/* Field wrapper — floating label */
.ar-field-wrap {
    position: relative;
    margin: 4px 0;
    flex: 1;
}

.ar-field-wrap label {
    position: absolute;
    left: 15px;
    top: 21px;
    font-size: 15px;
    color: var(--cor-texto-secundario);
    background-color: var(--cor-fundo-card);
    padding: 0 4px;
    pointer-events: none;
    transition: 0.2s ease-in-out;
    z-index: 1;
}

.ar-field-wrap input {
    height: 58px;
    border-radius: 10px;
    border: 2px solid var(--cor-principal);
    padding: 0 18px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    width: 100%;
    box-sizing: border-box;
    transition: border-color 0.2s ease-in-out;
}

.ar-field-wrap select {
    height: 58px;
    border-radius: 10px;
    border: 2px solid var(--cor-principal);
    padding: 0 18px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    width: 100%;
    box-sizing: border-box;
    appearance: none;
    cursor: pointer;
    transition: border-color 0.2s ease-in-out;
}

.ar-field-wrap input:focus,
.ar-field-wrap select:focus {
    outline: none;
    border-color: var(--cor-titulo);
}

.ar-field-wrap input:focus+label,
.ar-field-wrap input:not(:placeholder-shown)+label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.ar-field-wrap select+label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.ar-field-wrap:has(select)::after {
    content: "▾";
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--cor-principal);
    pointer-events: none;
    font-size: 0.9rem;
    z-index: 1;
}

/* Date display + button row */
.ar-date-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.ar-date-display {
    font-size: 2rem;
    font-weight: 400;
    color: var(--cor-principal);
}

/* Buttons */
.ar-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 52px;
    padding: 0 24px;
    min-width: 130px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    font-size: 1rem;
    font-weight: 400;
    cursor: pointer;
    transition: background 0.2s;
    margin: 0;
}

.ar-btn:hover {
    background: var(--cor-hover);
}

.ar-page button.ar-btn {
    padding: 0 24px;
    margin: 0;
    height: 52px;
}

.ar-btn.secondary {
    background: transparent;
    border: 2px solid var(--cor-principal);
    color: var(--cor-principal);
}

.ar-btn.secondary:hover {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
}

.ar-btns-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 4px;
}

/* Label-data text */
.label-data {
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--cor-principal);
    margin: 0;
}

/* Gestão de Conta section */
.ar-gestao-info {
    background: var(--cor-fundo-pagina);
    border-radius: 12px;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.ar-gestao-info h3 {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}

#ValorTotal {
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--cor-principal);
    margin: 0;
}

/* ── Múltiplos Registros table ── */
.tabela-registro {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.ar-multi-table {
    width: 100%;
    border-collapse: separate;
    border-radius: 15px;
    overflow: hidden;
    border-spacing: 0;
    border: 2px solid var(--cor-principal);
}

.ar-multi-table th {
    text-align: left;
    padding: 10px 14px;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--cor-principal);
    border-bottom: 1px solid var(--cor-principal);
    background: var(--cor-fundo-pagina);
}

.ar-multi-table td {
    padding: 10px 14px;
    font-size: 0.9rem;
    color: var(--cor-principal);
    border-bottom: 1px solid var(--cor-tinte-borda);
}

.ar-multi-table tr:last-child td {
    border-bottom: none;
}

.ar-multi-table th:last-child,
.ar-multi-table td:last-child {
    border-right: none;
}

/* FORMULÁRIO */
.multi-form {
    display: flex;
    gap: 16px;
    align-items: flex-end;
    flex-wrap: wrap;
}

.field-default {
    flex: 1;
    min-width: 160px;
}

.field-small {
    display: none;
    flex: 1;
    min-width: 130px;
}

.field-value {
    flex: 1;
    min-width: 140px;
}

.field-description {
    flex: 2;
    min-width: 200px;
}

.btn-add {
    flex-shrink: 0;
}

/* ══════════════════════════════════════════════════
   Grid utilities
══════════════════════════════════════════════════ */
.ar-span-2 { grid-column: span 2; }
.ar-span-3 { grid-column: 1 / -1; }

/* ══════════════════════════════════════════════════
   Tag Field wrapper
══════════════════════════════════════════════════ */
.ar-tag-field {
    position: relative;
    margin: 4px 0;
    flex: 1;
}

.ar-field-label {
    display: block;
    font-size: 12px;
    font-weight: 700;
    color: var(--cor-principal);
    margin-bottom: 5px;
    padding-left: 2px;
    letter-spacing: 0.02em;
}

/* ══════════════════════════════════════════════════
   Tag Picker
══════════════════════════════════════════════════ */
.ar-tp-container {
    position: relative;
}

.ar-tp-display {
    min-height: 58px;
    border-radius: 10px;
    border: 2px solid var(--cor-principal);
    padding: 8px 36px 8px 14px;
    cursor: pointer;
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;
    background: transparent;
    position: relative;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.ar-tp-display:hover { border-color: var(--cor-titulo); }

.ar-tp-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    flex: 1;
}

.ar-tp-ph {
    color: var(--cor-texto-secundario);
    font-size: 0.95rem;
    font-weight: 600;
}

.ar-tp-arr {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--cor-principal);
    font-size: 1rem;
    pointer-events: none;
    transition: transform 0.2s;
}

.ar-tp-display.open .ar-tp-arr { transform: translateY(-50%) rotate(180deg); }

.ar-tp-tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border-radius: 20px;
    padding: 3px 10px;
    font-size: 0.8rem;
    font-weight: 600;
    white-space: nowrap;
}

.ar-tp-tag-rm {
    background: none;
    border: none;
    color: var(--cor-texto-claro);
    opacity: 0.75;
    cursor: pointer;
    font-size: 1rem;
    padding: 0;
    line-height: 1;
    display: flex;
    align-items: center;
}
.ar-tp-tag-rm:hover { opacity: 1; color: var(--cor-texto-claro); }

/* Dropdown */
.ar-tp-dd {
    position: absolute;
    top: calc(100% + 4px);
    left: 0;
    right: 0;
    background: var(--cor-fundo-card);
    border: 2px solid var(--cor-principal);
    border-radius: 10px;
    z-index: 200;
    max-height: 220px;
    overflow-y: auto;
    box-shadow: 0 6px 20px var(--sombra-flutuante);
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2px;
    padding: 6px;
}

.ar-tp-option {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    border: none;
    background: transparent;
    border-radius: 8px;
    cursor: pointer;
    font-size: 0.88rem;
    color: var(--cor-principal);
    font-weight: 500;
    text-align: left;
    transition: background 0.12s;
    width: 100%;
}
.ar-tp-option:hover { background: var(--cor-tinte-medio); }

.ar-tp-option-sel {
    background: var(--cor-principal) !important;
    color: var(--cor-texto-claro) !important;
}

.ar-tp-opt-check {
    width: 18px;
    height: 18px;
    border-radius: 5px;
    border: 2px solid currentColor;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    flex-shrink: 0;
}

/* ══════════════════════════════════════════════════
   Institution split amounts
══════════════════════════════════════════════════ */
.ar-inst-amounts-wrap {
    margin-top: 8px;
    background: var(--cor-tinte-suave);
    border-radius: 10px;
    padding: 10px 12px;
    border: 1px solid var(--cor-tinte-borda);
}

.ar-inst-amounts-title {
    font-size: 10px;
    font-weight: 700;
    color: var(--cor-principal);
    opacity: 0.65;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin: 0 0 8px 0;
}

.ar-inst-amount-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 6px;
}
.ar-inst-amount-row:last-child { margin-bottom: 0; }

.ar-inst-name {
    font-size: 0.83rem;
    font-weight: 700;
    color: var(--cor-principal);
    min-width: 90px;
    max-width: 110px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.ar-inst-amt-input {
    flex: 1;
    height: 34px;
    border-radius: 8px;
    border: 1px solid var(--cor-principal);
    padding: 0 10px;
    font-size: 0.88rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: var(--cor-fundo-card);
    outline: none;
    box-sizing: border-box;
}
.ar-inst-amt-input:focus { border-color: var(--cor-titulo); border-width: 2px; }

/* ══════════════════════════════════════════════════
   Recurring section
══════════════════════════════════════════════════ */
.ar-recurring-wrap { padding: 0 4px; }

.ar-recurring-toggle {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    cursor: pointer;
    user-select: none;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--cor-principal);
}
.ar-recurring-toggle:hover .ar-checkbox-btn { border-color: var(--cor-titulo); }

.ar-checkbox-btn {
    width: 22px;
    height: 22px;
    border-radius: 6px;
    border: 2px solid var(--cor-principal);
    background: transparent;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: background 0.15s, border-color 0.15s;
}
.ar-checkbox-btn.active { background: var(--cor-principal); border-color: var(--cor-principal); }

.ar-recurring-body {
    margin-top: 12px;
    margin-left: 32px;
    padding-left: 16px;
    border-left: 2px solid var(--cor-tinte-borda);
}

.ar-recurring-group { margin-bottom: 14px; }
.ar-recurring-group:last-child { margin-bottom: 0; }

.ar-group-label {
    display: block;
    font-size: 10px;
    font-weight: 700;
    color: var(--cor-principal);
    opacity: 0.6;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    margin-bottom: 8px;
}

/* ── Pills (periodicidade, semana, mês, meses) ── */
.ar-pills {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.ar-pill {
    padding: 6px 16px;
    border-radius: 20px;
    border: 2px solid var(--cor-principal);
    background: transparent;
    color: var(--cor-principal);
    font-size: 0.83rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    line-height: 1;
}
.ar-pill:hover { background: var(--cor-tinte-medio); }
.ar-pill.active { background: var(--cor-principal); color: var(--cor-texto-claro); }

.ar-pill-sm { padding: 5px 9px; font-size: 0.78rem; }

.ar-daygrid { gap: 4px; }

.ar-select-small {
    height: 40px;
    border-radius: 8px;
    border: 2px solid var(--cor-principal);
    padding: 0 12px;
    font-size: 0.88rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    cursor: pointer;
    appearance: none;
    margin-top: 4px;
    outline: none;
}
.ar-select-small:focus { border-color: var(--cor-titulo); }

/* ══════════════════════════════════════════════════
   Clear-on-focus state indicator
══════════════════════════════════════════════════ */
.ar-field-submitted {
    background: var(--cor-fundo-campo) !important;
}
.ar-field-submitted + label {
    color: var(--cor-principal) !important;
    opacity: 0.7;
}

/* Empty lote row */
.ar-lote-vazio {
    text-align: center;
    color: var(--cor-texto-secundario);
    font-style: italic;
    padding: 20px;
}

/* Edit/delete action buttons in table */
.ar-lote-actions {
    display: flex;
    gap: 4px;
    align-items: center;
}
.ar-lote-btn {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 7px;
    background: transparent;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    transition: background 0.14s, color 0.14s;
}
.ar-lote-btn:hover { background: var(--cor-tinte-medio); }
.ar-lote-btn.delete:hover { background: var(--red-100); color: var(--red-700); }
.ar-lote-btn.edit:hover { background: var(--cor-tinte-medio); color: var(--cor-principal); }

@import "root.css";

/* ── Adicionar Registros page ── */

/* ── Tab header ── */
.ar-tabs {
    display: flex;
    gap: 0;
    margin-bottom: 0;
}

.ar-tab {
    padding: 10px 28px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-titulo);
    cursor: pointer;
    background: var(--cor-fundo-card);
    border: 2px solid var(--cor-principal);
    border-bottom: none;
    border-radius: 2px 2px 0 0;
    position: relative;
    bottom: -2px;
    transition: background 0.15s;
    text-decoration: none;
    user-select: none;
}

.ar-tab.ativo {
    background: var(--cor-fundo-card);
    color: var(--cor-hover);
    z-index: 1;
}

.ar-tab:not(.ativo) {
    background: var(--cor-fundo-inativo);
    color: var(--cor-principal);
}

/* ── Main form card ── */
.ar-card {
    background: var(--cor-fundo-card);
    border-radius: 0 20px 20px 20px;
    box-shadow: 0px 4px 4px var(--sombra-caixa);
    border-left: 2px solid var(--cor-principal);
    padding: 28px 24px;
    display: flex;
    gap: 32px;
    align-items: flex-start;
    flex-wrap: wrap;
}

/* Mascot column */
.ar-mascot {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
    flex-shrink: 0;
}

.ar-mascot-img {
    width: 200px;
    border: 1px solid var(--cor-borda-mascote);
    box-shadow: 0px 4px 4px var(--sombra-caixa);
    border-radius: 4px;
    display: block;
}

/* Form column */
.ar-form-col {
    flex: 1;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.formulario-adicionar-gasto {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    padding: 1rem;
}

.botao-formulario {
    display: flex;
    align-items: end;
    gap: 1rem;
}

/* Field wrapper — floating label */
.ar-field-wrap {
    position: relative;
    margin: 4px 0;
    flex: 1;
}

.ar-field-wrap label {
    position: absolute;
    left: 15px;
    top: 21px;
    font-size: 15px;
    color: var(--cor-texto-secundario);
    background-color: var(--cor-fundo-card);
    padding: 0 4px;
    pointer-events: none;
    transition: 0.2s ease-in-out;
    z-index: 1;
}

.ar-field-wrap input {
    height: 58px;
    border-radius: 10px;
    border: 2px solid var(--cor-principal);
    padding: 0 18px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    width: 100%;
    box-sizing: border-box;
    transition: border-color 0.2s ease-in-out;
}

.ar-field-wrap select {
    height: 58px;
    border-radius: 10px;
    border: 2px solid var(--cor-principal);
    padding: 0 18px;
    font-size: 1rem;
    font-weight: 600;
    color: var(--cor-principal);
    background: transparent;
    width: 100%;
    box-sizing: border-box;
    appearance: none;
    cursor: pointer;
    transition: border-color 0.2s ease-in-out;
}

.ar-field-wrap input:focus,
.ar-field-wrap select:focus {
    outline: none;
    border-color: var(--cor-titulo);
}

.ar-field-wrap input:focus+label,
.ar-field-wrap input:not(:placeholder-shown)+label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.ar-field-wrap select+label {
    top: -1px;
    font-size: 12px;
    color: var(--cor-principal);
}

.ar-field-wrap:has(select)::after {
    content: "▾";
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--cor-principal);
    pointer-events: none;
    font-size: 0.9rem;
    z-index: 1;
}

/* Date display + button row */
.ar-date-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.ar-date-display {
    font-size: 2rem;
    font-weight: 400;
    color: var(--cor-principal);
}

/* Buttons */
.ar-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: 52px;
    padding: 0 24px;
    min-width: 130px;
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
    border: none;
    border-radius: 10px;
    font-size: 1rem;
    font-weight: 400;
    cursor: pointer;
    transition: background 0.2s;
    margin: 0;
}

.ar-btn:hover {
    background: var(--cor-hover);
}

.ar-page button.ar-btn {
    padding: 0 24px;
    margin: 0;
    height: 52px;
}

.ar-btn.secondary {
    background: transparent;
    border: 2px solid var(--cor-principal);
    color: var(--cor-principal);
}

.ar-btn.secondary:hover {
    background: var(--cor-principal);
    color: var(--cor-texto-claro);
}

.ar-btns-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 4px;
}

/* Label-data text */
.label-data {
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--cor-principal);
    margin: 0;
}

/* Gestão de Conta section */
.ar-gestao-info {
    background: var(--cor-fundo-pagina);
    border-radius: 12px;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.ar-gestao-info h3 {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cor-titulo);
    margin: 0;
}

#ValorTotal {
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--cor-principal);
    margin: 0;
}

/* ── Múltiplos Registros table ── */
.tabela-registro {
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
}

.ar-multi-table {
    width: 100%;
    border-collapse: separate;
    border-radius: 15px;
    overflow: hidden;
    border-spacing: 0;
    border: 2px solid var(--cor-principal);
}

.ar-multi-table th {
    text-align: left;
    padding: 10px 14px;
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--cor-principal);
    border-bottom: 1px solid var(--cor-principal);
    background: var(--cor-fundo-pagina);
}

.ar-multi-table td {
    padding: 10px 14px;
    font-size: 0.9rem;
    color: var(--cor-principal);
    border-bottom: 1px solid var(--cor-tinte-borda);
}

.ar-multi-table tr:last-child td {
    border-bottom: none;
}

.ar-multi-table th:last-child,
.ar-multi-table td:last-child {
    border-right: none;
}

/* FORMULÁRIO */
.multi-form {
    display: flex;
    gap: 16px;
    align-items: flex-end;
    flex-wrap: wrap;
}

.field-default {
    flex: 1;
    min-width: 160px;
}

.field-small {
    display: none;
    flex: 1;
    min-width: 130px;
}

.field-value {
    flex: 1;
    min-width: 140px;
}

.field-description {
    flex: 2;
    min-width: 200px;
}

.btn-add {
    flex-shrink: 0;
}

/* ══════════════════════════════════════════════════
   Grid utilities
══════════════════════════════════════════════════ */
.ar-span-2 { grid-column: span 2; }
.ar-span-3 { grid-column: 1 / -1; }

/* ══════════════════════════════════════════════════
   Tag Field wrapper
══════════════════════════════════════════════════ */
.ar-tag-field {
    position: relative;
    margin: 4px 0;
    flex: 1;
}

.ar-field-label {
    display: block;
    font-size: 12px;
    font-weight: 700;
    color: var(--cor-principal);
    margin-bottom: 5px;
    padding-left: 2px;
    letter-spacing: 0.02em;
}

